// Content for Same Same, Different (node g04, ages 3-6): reworked to GDD 04 v2 (mechanic-embodying).
// "Equal inside, wonderfully different." The gender-root game and the start of the Gender & Respect thread:
// 82 researched, India-grounded scenarios across six categories, each re-encoded to one of the seven shared
// v2 play actions (reflect / role-play / strike-rewrite / branch / sort / match / build): no binary "tap the
// right card", led by erasing silly gender rules. Toys & colours are for everyone; anyone can do anything;
// everyone can be strong AND gentle; we're equal inside, wonderfully different outside (India colourism /
// Dark is Beautiful); fair play means everyone belongs. Both directions (frees girls AND boys); never
// preachy. Rendered by the shared engine (components/games/v2-engine.tsx). gameId "same-same". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // Toys for all
  {"id":"ss-001","cat":"toys-for-all","type":"sort","hook":"Lensy found some toys. Can every kid play?","items":[{"id":"a","text":"A doll, for any kid that likes it"},{"id":"b","text":"A truck, only for boys"},{"id":"c","text":"Blocks, for anyone"},{"id":"d","text":"A tea set, only for girls"},{"id":"e","text":"A kite, for any kid at all"},{"id":"f","text":"A cooking set, just for girls"}],"bins":[{"id":"fair","label":"True & fair","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"fair","b":"silly","c":"fair","d":"silly","e":"fair","f":"silly"},"relearn":"Toys are for any kid that enjoys them, not for one kind of kid.","persona":"Vihaan","source":"gender & play research"},
  {"id":"ss-002","cat":"toys-for-all","type":"strike-rewrite","hook":"Vihaan says \"trucks are boys' toys.\"","myth":{"un":"Trucks are only for boys.","re":"Anyone can play with trucks.","why":"A toy doesn't know who's holding it."},"relearn":"Anyone can play with trucks, or dolls, or blocks.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-003","cat":"toys-for-all","type":"role-play","hook":"A toy is feeling lonely on the shelf.","setup":"Say it loud so the toy hears.","yourLine":[{"text":"\"Anyone can play with you!\"","best":true},{"text":"\"You're only for some kids.\""}],"relearn":"Saying \"anyone can play\" out loud makes it true on the playground too.","persona":"Kabir","source":"voice / audio-first"},
  {"id":"ss-004","cat":"toys-for-all","type":"match","hook":"Match each kid to a toy they love.","pairs":[{"left":"A girl keen on building","right":"Blocks and tools"},{"left":"A boy keen on caring","right":"A doll and a play-kitchen"},{"left":"A kid keen on everything","right":"A bit of it all"},{"left":"A girl keen on cricket","right":"A bat and ball"},{"left":"A boy keen on dressing dolls","right":"A doll and tiny clothes"}],"relearn":"Kids love all kinds of toys; the toy doesn't pick the kid.","persona":"any","source":"gender & play"},
  {"id":"ss-005","cat":"toys-for-all","type":"build","hook":"Build a toy box for the whole class.","prompt":"Drag in toys for everyone to share.","pieces":["blocks","dolls","trucks","play-kitchen","cricket bat","art set"],"mode":"assemble","key":["blocks","dolls","trucks","play-kitchen","cricket bat","art set"],"relearn":"A great toy box has something for everyone, and everyone may share it all.","persona":"any","source":"inclusion"},
  {"id":"ss-006","cat":"toys-for-all","type":"branch","hook":"Your friend says \"you can't play with that, it's for girls.\"","options":[{"text":"Say \"toys are for everyone\" and play together","consequence":"You both have fun; the silly rule disappears.","outcome":"fair","best":true},{"text":"Put it down and feel sad","consequence":"You miss out, and the rule wasn't even true.","outcome":"missed"}],"debrief":"A kind, clear \"toys are for everyone\" is all it takes.","relearn":"No one can tell you a toy isn't for you.","persona":"Vihaan","source":"peer norms"},
  {"id":"ss-007","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Dolls are only for girls.\"","myth":{"un":"Dolls are only for girls.","re":"Boys can love dolls too; caring is for everyone.","why":"Playing at caring helps every child practise being kind."},"relearn":"Boys who play with dolls are practising care, and that's wonderful.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-008","cat":"toys-for-all","type":"reflect","hook":"Lensy: what's YOUR favourite thing to play?","prompt":"Point to one.","options":["Building","Pretend cooking","Running games","Drawing"],"affirm":"Whatever you love is exactly right for you. Play is for everyone.","relearn":"Your favourite play is yours, no toy is off-limits because of your gender.","persona":"any","source":"autonomy"},
  {"id":"ss-009","cat":"toys-for-all","type":"sort","hook":"Sort: fair sharing, or not fair?","items":[{"id":"a","text":"Everyone gets a turn with the ball"},{"id":"b","text":"Only boys get the ball"},{"id":"c","text":"Take turns with the dolls"},{"id":"d","text":"Girls can't use the blocks"},{"id":"e","text":"We share the drum, one at a time"},{"id":"f","text":"Boys can't touch the skipping rope"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Taking turns is fair; keeping toys from someone for being a girl or boy is not.","persona":"Aria","source":"fairness"},
  {"id":"ss-010","cat":"toys-for-all","type":"match","hook":"A toy and the fun it gives, match them.","pairs":[{"left":"Blocks","right":"Building tall towers"},{"left":"Doll","right":"Pretend caring"},{"left":"Ball","right":"Running and throwing"},{"left":"Toy kitchen","right":"Cooking a pretend feast"},{"left":"Toy car","right":"Zooming around the mat"}],"relearn":"Every toy is a kind of fun, open to every kid.","persona":"any","source":"play"},
  {"id":"ss-011","cat":"toys-for-all","type":"strike-rewrite","hook":"\"You play with the wrong toys.\"","myth":{"un":"Some kids play with the 'wrong' toys.","re":"There are no wrong toys; there's just what you enjoy.","why":"Fun isn't right or wrong."},"relearn":"There are no wrong toys for you.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-012","cat":"toys-for-all","type":"role-play","hook":"A new friend is unsure if they can join the blocks.","setup":"Welcome them in. Say:","yourLine":[{"text":"\"Come build with us, anyone can!\"","best":true},{"text":"\"This is only for us.\""}],"relearn":"Inviting everyone to play is how good friends play.","persona":"Kabir","source":"inclusion / voice"},
  {"id":"ss-013","cat":"toys-for-all","type":"build","hook":"Build a play corner where everyone belongs.","prompt":"Add a sign for the corner.","pieces":["\"Everyone welcome\"","\"Anyone can play\"","\"Boys only\"","\"Share and take turns\""],"mode":"assemble","key":["\"Everyone welcome\"","\"Anyone can play\"","\"Share and take turns\""],"relearn":"A play corner for everyone says: welcome, anyone can play, take turns.","persona":"any","source":"inclusion"},
  {"id":"ss-014","cat":"toys-for-all","type":"reflect","hook":"Megha-moment: ask a grown-up to play YOUR favourite with you.","prompt":"Who will you ask?","options":["Amma","Appa","Dadi/Nani","Big sibling"],"affirm":"Sharing your play with a grown-up is the best, and they'll see toys are for everyone too.","relearn":"Play is to share; invite your grown-ups in.","persona":"Megha","source":"co-play"},

  // Colours for all
  {"id":"ss-015","cat":"colours-for-all","type":"strike-rewrite","hook":"Vihaan says \"pink is a girl colour.\"","myth":{"un":"Pink is a girl colour.","re":"Colours are for everyone; pink is just a colour.","why":"Long ago pink was even called a 'boy' colour, fashions change, colours don't have a gender."},"relearn":"Every colour is for every kid.","persona":"Vihaan","source":"colour & gender history"},
  {"id":"ss-016","cat":"colours-for-all","type":"build","hook":"Dress the kid in any colours you like.","prompt":"Pick colours for the outfit (any you like!).","pieces":["pink","blue","yellow","green","purple","orange"],"mode":"assemble","key":["pink","blue","yellow","green","purple","orange"],"relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"autonomy / dress-up"},
  {"id":"ss-017","cat":"colours-for-all","type":"sort","hook":"Sort: true, or silly rule?","items":[{"id":"a","text":"Anyone can like blue"},{"id":"b","text":"Boys can't wear pink"},{"id":"c","text":"Anyone can like pink"},{"id":"d","text":"Purple is only for girls"},{"id":"e","text":"Anyone can like green"},{"id":"f","text":"Yellow is only for boys"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"Anyone can like any colour; rules that ban a colour are just silly.","persona":"Vihaan","source":"colour & gender"},
  {"id":"ss-018","cat":"colours-for-all","type":"role-play","hook":"A boy loves his pink shirt but someone laughed.","setup":"Help him stand tall. Say:","yourLine":[{"text":"\"Pink looks great. Colours are for everyone.\"","best":true},{"text":"\"Take it off then.\""}],"relearn":"You can cheer a friend for wearing any colour he loves.","persona":"Faizan-type","source":"voice / support"},
  {"id":"ss-019","cat":"colours-for-all","type":"match","hook":"Match the kid to the colour they chose, all happy.","pairs":[{"left":"Boy picked pink","right":"Big smile"},{"left":"Girl picked black","right":"Happy grin"},{"left":"Kid picked rainbow","right":"Bright laugh"},{"left":"Boy picked purple","right":"Proud cheer"},{"left":"Girl picked blue","right":"Wide smile"}],"relearn":"When kids pick their own colours, everyone's happy.","persona":"any","source":"autonomy"},
  {"id":"ss-020","cat":"colours-for-all","type":"branch","hook":"Someone says your favourite colour is \"for the other gender.\"","options":[{"text":"Say \"colours are for everyone\" and keep loving it","consequence":"You keep your favourite; the rule fades.","outcome":"fair","best":true},{"text":"Pick a different colour to fit in","consequence":"You give up something you love for a silly rule.","outcome":"missed"}],"debrief":"Your favourite colour is yours to keep.","relearn":"No colour belongs to one gender.","persona":"Vihaan","source":"peer norms"},
  {"id":"ss-021","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Blue is only for boys.\"","myth":{"un":"Blue is only for boys.","re":"Anyone can love blue, or any colour.","why":"Colours are just light and fun, not rules."},"relearn":"Blue, pink, green, all colours are for all kids.","persona":"Aria","source":"colour & gender"},
  {"id":"ss-022","cat":"colours-for-all","type":"reflect","hook":"Lensy: what colour makes YOU happy?","prompt":"Point to it.","options":["Pink","Blue","Yellow","A mix!"],"affirm":"That's your colour, and it's a perfect choice. No colour is off-limits.","relearn":"Your favourite colour is a happy, free choice.","persona":"any","source":"autonomy"},
  {"id":"ss-023","cat":"colours-for-all","type":"sort","hook":"Sort the crayons, who can use them?","items":[{"id":"a","text":"Pink, for anyone"},{"id":"b","text":"Blue, for boys only"},{"id":"c","text":"Green, for anyone"},{"id":"d","text":"Purple, for girls only"},{"id":"e","text":"Yellow, for anyone"},{"id":"f","text":"Red, for boys only"}],"bins":[{"id":"all","label":"For anyone","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"all","b":"silly","c":"all","d":"silly","e":"all","f":"silly"},"relearn":"Every crayon is for every kid.","persona":"any","source":"colour & gender"},
  {"id":"ss-024","cat":"colours-for-all","type":"role-play","hook":"You're choosing a balloon at a party.","setup":"The seller asks which you'd like. Say:","yourLine":[{"text":"\"The one I love most, please!\"","best":true},{"text":"\"The one that's for my gender.\""}],"relearn":"You choose what you love, not what a rule says.","persona":"any","source":"autonomy / voice"},
  {"id":"ss-025","cat":"colours-for-all","type":"build","hook":"Paint a rainbow room for the whole class.","prompt":"Add colours everyone can enjoy.","pieces":["pink wall","blue wall","yellow sun","green plants"],"mode":"assemble","key":["pink wall","blue wall","yellow sun","green plants"],"relearn":"A room for everyone has all the colours, shared by all.","persona":"any","source":"inclusion"},
  {"id":"ss-026","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Wearing the wrong colour is embarrassing.\"","myth":{"un":"Wearing the 'wrong' colour for your gender is embarrassing.","re":"There's no wrong colour; wear what you love proudly.","why":"Pride beats a made-up rule."},"relearn":"Wear your favourite colour proudly.","persona":"Faizan-type","source":"self-esteem"},

  // Anyone can
  {"id":"ss-027","cat":"anyone-can","type":"match","hook":"Anyone can do these. Match the kid to the activity.","pairs":[{"left":"A girl","right":"Climbing the highest"},{"left":"A boy","right":"Cooking yummy food"},{"left":"Any kid","right":"Leading the game"},{"left":"A girl with a ball","right":"Scoring the goal"},{"left":"A boy with a doll","right":"Caring gently"}],"relearn":"Climbing, cooking, leading, caring, anyone can do any of it.","persona":"Aria","source":"anyone-can"},
  {"id":"ss-028","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't climb high.\"","myth":{"un":"Girls can't climb high.","re":"Girls can climb just as high; bodies grow strong with practice.","why":"Practice, not gender, builds climbing."},"relearn":"Girls can climb, run and jump as high as anyone.","persona":"Aria","source":"physical ability"},
  {"id":"ss-029","cat":"anyone-can","type":"role-play","hook":"A girl is unsure if she can lead the game.","setup":"Cheer her on. Say:","yourLine":[{"text":"\"You'd be a great leader, go for it!\"","best":true},{"text":"\"Leaders are usually boys.\""}],"relearn":"Anyone can be the leader; cheering each other helps.","persona":"Aria","source":"leadership / voice"},
  {"id":"ss-030","cat":"anyone-can","type":"sort","hook":"Who can do these jobs? Sort it.","items":[{"id":"a","text":"A girl doctor"},{"id":"b","text":"Only men can be doctors"},{"id":"c","text":"A boy nurse"},{"id":"d","text":"Only women can be nurses"},{"id":"e","text":"A girl engineer"},{"id":"f","text":"Only men can build things"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"silly","label":"Silly rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Doctor, nurse, engineer, anyone can be anything (more in Can-Do Kids).","persona":"any","source":"occupations"},
  {"id":"ss-031","cat":"anyone-can","type":"strike-rewrite","hook":"\"Boys can't cook.\"","myth":{"un":"Boys can't cook.","re":"Boys can be wonderful cooks; cooking is for everyone.","why":"Many top chefs are men; cooking is a skill, not a gender."},"relearn":"Anyone can cook, and it's a great skill to have.","persona":"Faizan-type","source":"occupations"},
  {"id":"ss-032","cat":"anyone-can","type":"branch","hook":"The group says only boys can be the team captain.","options":[{"text":"Say \"anyone can be captain\" and pick fairly","consequence":"A great captain is chosen on skill, not gender.","outcome":"fair","best":true},{"text":"Go along with boys-only","consequence":"A good captain gets left out for no reason.","outcome":"unfair"}],"debrief":"Captains are picked for being good leaders, not for being boys.","relearn":"Anyone can lead the team.","persona":"Aria","source":"leadership"},
  {"id":"ss-033","cat":"anyone-can","type":"reflect","hook":"Lensy: what do YOU want to try?","prompt":"Point to a dream.","options":["Climb high","Cook a feast","Lead a team","Build something"],"affirm":"You can absolutely try that. Anyone can.","relearn":"Your dreams aren't fenced in by being a girl or a boy.","persona":"any","source":"aspiration"},
  {"id":"ss-034","cat":"anyone-can","type":"role-play","hook":"A boy wants to join the dancing.","setup":"Make room for him. Say:","yourLine":[{"text":"\"Come dance, anyone can!\"","best":true},{"text":"\"Dancing's for girls.\""}],"relearn":"Boys can dance beautifully; anyone can join in.","persona":"Faizan-type","source":"voice / inclusion"},
  {"id":"ss-035","cat":"anyone-can","type":"match","hook":"Match each kid to what they're great at.","pairs":[{"left":"Girl loving maths","right":"Solving puzzles"},{"left":"Boy loving art","right":"Painting pictures"},{"left":"Kid loving animals","right":"Caring for pets"},{"left":"Girl loving building","right":"Making tall towers"},{"left":"Boy loving music","right":"Singing songs"}],"relearn":"Kids are great at all sorts of things, no gender required.","persona":"any","source":"ability"},
  {"id":"ss-036","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls aren't good at maths.\"","myth":{"un":"Girls aren't good at maths.","re":"Girls are great at maths; it's a skill anyone grows.","why":"Ability comes from practice, not gender."},"relearn":"Anyone can be brilliant at maths with practice.","persona":"Aria","source":"ability beliefs"},
  {"id":"ss-037","cat":"anyone-can","type":"sort","hook":"Sort: anyone can, or silly rule?","items":[{"id":"a","text":"A boy can sew"},{"id":"b","text":"Only girls can sew"},{"id":"c","text":"A girl can fix a bike"},{"id":"d","text":"Only boys fix things"},{"id":"e","text":"A boy can knit"},{"id":"f","text":"Only girls can knit"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"silly","label":"Silly rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Sewing, fixing, knitting, anyone can learn anything.","persona":"any","source":"skills"},
  {"id":"ss-038","cat":"anyone-can","type":"build","hook":"Build a 'things I can try' chart.","prompt":"Add things anyone can try.","pieces":["climb","cook","lead","dance","build","care"],"mode":"assemble","key":["climb","cook","lead","dance","build","care"],"relearn":"Your 'can-try' list is as long as you want; nothing's off-limits.","persona":"any","source":"aspiration"},
  {"id":"ss-039","cat":"anyone-can","type":"reflect","hook":"Aria-moment: is it okay for YOU to be the loud, leading one?","prompt":"What do you think?","options":["Yes!","I'm not sure","I'd like to try"],"affirm":"Yes, it is. Big voices and leading are for you too.","relearn":"Leading and being heard are for every kid, including quiet 'good girls'.","persona":"Aria","source":"agency"},
  {"id":"ss-040","cat":"anyone-can","type":"role-play","hook":"You want to try something new that people call 'not for you'.","setup":"Say it brave:","yourLine":[{"text":"\"I can try anything I want to.\"","best":true},{"text":"\"Maybe it's not for me.\""}],"relearn":"Saying \"I can try\" is the start of every new skill.","persona":"any","source":"growth mindset / voice"},

  // Strong & gentle
  {"id":"ss-041","cat":"strong-gentle","type":"strike-rewrite","hook":"Vihaan says \"big boys don't cry.\"","myth":{"un":"Big boys don't cry.","re":"Everyone cries; tears are for every kid.","why":"Feelings aren't a gender (see Feelings Friends)."},"relearn":"Crying is okay for boys and girls; it helps big feelings out.","persona":"Vihaan","source":"emotions (links g01)"},
  {"id":"ss-042","cat":"strong-gentle","type":"sort","hook":"Sort each kid: showing strong, or showing gentle? Anyone can do both.","items":[{"id":"a","text":"A girl lifting a big block"},{"id":"b","text":"A boy rocking a baby softly"},{"id":"c","text":"A boy carrying a water pot"},{"id":"d","text":"A girl hugging a friend softly"},{"id":"e","text":"A girl leading the game loudly"},{"id":"f","text":"A boy patting a puppy gently"}],"bins":[{"id":"strong","label":"Strong","valence":"pos"},{"id":"gentle","label":"Gentle","valence":"pos"}],"key":{"a":"strong","b":"gentle","c":"strong","d":"gentle","e":"strong","f":"gentle"},"relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"emotional range"},
  {"id":"ss-043","cat":"strong-gentle","type":"role-play","hook":"A boy is holding back tears so he looks 'tough'.","setup":"Let him know it's okay. Say:","yourLine":[{"text":"\"It's okay to cry. I'm here.\"","best":true},{"text":"\"Be tough, don't cry.\""}],"relearn":"Helping a friend let tears out is a strong, kind thing to do.","persona":"Faizan-type","source":"voice / empathy"},
  {"id":"ss-044","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Girls are too gentle to be strong.\"","myth":{"un":"Girls are too gentle to be strong.","re":"Girls can be strong AND gentle, both at once.","why":"Strength and gentleness live in everyone."},"relearn":"You can be gentle and strong; they're not opposites.","persona":"Aria","source":"emotional range"},
  {"id":"ss-045","cat":"strong-gentle","type":"branch","hook":"A friend fell and is crying. Others say \"don't be a baby.\"","options":[{"text":"Help them up and say \"it's okay to cry\"","consequence":"They calm down; you were the kind one.","outcome":"kind","best":true},{"text":"Join the others teasing","consequence":"They feel worse and more alone.","outcome":"unkind"}],"debrief":"Comforting a crying friend is the strong, brave choice.","relearn":"Kindness when someone cries is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-046","cat":"strong-gentle","type":"match","hook":"Match the kid to the feeling. (Every feeling is for everyone!)","pairs":[{"left":"A scared boy","right":"Okay: scared is for anyone"},{"left":"An angry girl","right":"Okay: angry is for anyone"},{"left":"A sad boy","right":"Okay: sad is for anyone"},{"left":"A brave girl","right":"Okay: brave is for anyone"},{"left":"A gentle boy","right":"Okay: gentle is for anyone"}],"relearn":"Every feeling is okay for every kid.","persona":"any","source":"emotions"},
  {"id":"ss-047","cat":"strong-gentle","type":"reflect","hook":"Lensy: can you be both gentle and strong?","prompt":"What do you think?","options":["Yes, both!","Only one","I'm both already"],"affirm":"Yes, you can be both, and you already are.","relearn":"You hold both gentle and strong inside you.","persona":"any","source":"self-concept"},
  {"id":"ss-048","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Boys have to be tough all the time.\"","myth":{"un":"Boys must be tough all the time.","re":"Boys can be soft, scared, silly and gentle too.","why":"No one is tough every minute; that's not real."},"relearn":"Boys get to feel everything, not just 'tough'.","persona":"Vihaan","source":"emotional health"},
  {"id":"ss-049","cat":"strong-gentle","type":"role-play","hook":"You feel a big feeling and want to let it out.","setup":"Say your feeling out loud:","yourLine":[{"text":"\"I feel ___, and that's okay.\"","best":true},{"text":"\"I should hide it.\""}],"relearn":"Naming a feeling out loud helps it feel smaller.","persona":"Aria","source":"affect labelling / voice"},
  {"id":"ss-050","cat":"strong-gentle","type":"sort","hook":"Sort: kind-strong, or just unkind?","items":[{"id":"a","text":"Carrying a heavy bag for a friend"},{"id":"b","text":"Pushing a friend to look tough"},{"id":"c","text":"Standing up gently for someone"},{"id":"d","text":"Teasing a crying friend"},{"id":"e","text":"Helping a little kid up the slide"},{"id":"f","text":"Calling a crier 'a baby'"}],"bins":[{"id":"strong","label":"Kind & strong","valence":"pos"},{"id":"unkind","label":"Just unkind","valence":"neg"}],"key":{"a":"strong","b":"unkind","c":"strong","d":"unkind","e":"strong","f":"unkind"},"relearn":"Real strength is kind; pushing and teasing are just unkind.","persona":"any","source":"values"},
  {"id":"ss-051","cat":"strong-gentle","type":"build","hook":"Build a superhero who is BOTH strong and gentle.","prompt":"Pick their powers.","pieces":["super strength","big kindness","brave heart","gentle hands","listens well"],"mode":"assemble","key":["super strength","big kindness","brave heart","gentle hands","listens well"],"relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-052","cat":"strong-gentle","type":"reflect","hook":"Think of a time you were gentle with someone.","prompt":"How did it feel?","options":["Good","Warm","Proud","Happy"],"affirm":"That gentleness is a strength you carry. Use it lots.","relearn":"Gentleness is something to be proud of.","persona":"any","source":"self-esteem"},

  // Different is wonderful
  {"id":"ss-053","cat":"different-wonderful","type":"sort","hook":"We're same inside, different outside. Sort these.","items":[{"id":"a","text":"We all have a beating heart"},{"id":"b","text":"We have different skin colours"},{"id":"c","text":"We all have feelings"},{"id":"d","text":"We like different foods"},{"id":"e","text":"We all need love and friends"},{"id":"f","text":"We speak different home languages"}],"bins":[{"id":"same","label":"Same inside","valence":"pos"},{"id":"diff","label":"Different (and good!)","valence":"neutral"}],"key":{"a":"same","b":"diff","c":"same","d":"diff","e":"same","f":"diff"},"relearn":"Inside we're alike; outside we're different, and that's wonderful.","persona":"any","source":"equality / diversity"},
  {"id":"ss-054","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Being different is bad.\"","myth":{"un":"Being different is bad.","re":"Being different is wonderful; it makes the world interesting.","why":"Imagine if everyone were the same, how dull!"},"relearn":"Different is wonderful, not wrong.","persona":"any","source":"diversity"},
  {"id":"ss-055","cat":"different-wonderful","type":"match","hook":"Match the difference to why it's lovely.","pairs":[{"left":"Different languages","right":"So many ways to say hello"},{"left":"Different foods","right":"So many yummy tastes"},{"left":"Different looks","right":"Everyone is one of a kind"},{"left":"Different festivals","right":"So many days to celebrate"},{"left":"Different songs","right":"So many tunes to share"}],"relearn":"Our differences add colour to the world.","persona":"Kabir","source":"diversity"},
  {"id":"ss-056","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Fair skin is prettier.\"","myth":{"un":"Fair skin is prettier than dark skin.","re":"Every skin colour is beautiful.","why":"Beauty comes in every shade (Dark is Beautiful)."},"relearn":"All skin colours are lovely; no shade is 'better'.","persona":"any","source":"India colourism"},
  {"id":"ss-057","cat":"different-wonderful","type":"build","hook":"Build a class photo with all kinds of kids.","prompt":"Add classmates of every kind.","pieces":["different skin tones","glasses","a wheelchair","different heights","big smiles"],"mode":"assemble","key":["different skin tones","glasses","a wheelchair","different heights","big smiles"],"relearn":"A real class is wonderfully different, and every kid belongs.","persona":"any","source":"inclusion"},
  {"id":"ss-058","cat":"different-wonderful","type":"reflect","hook":"Lensy: what makes YOU one of a kind?","prompt":"Point to one.","options":["My laugh","My ideas","How I look","What I love"],"affirm":"That's a wonderful part of you. Nobody else is just like you.","relearn":"Your differences make you, you, and that's a gift.","persona":"any","source":"self-esteem"},
  {"id":"ss-059","cat":"different-wonderful","type":"branch","hook":"A new kid speaks a different language and looks unsure.","options":[{"text":"Smile and teach each other a word","consequence":"You make a friend and learn something new.","outcome":"kind","best":true},{"text":"Stay away because they're different","consequence":"You both miss out on a friend.","outcome":"missed"}],"debrief":"Difference is the start of something interesting, not a reason to stay away.","relearn":"A kid who's different from you can be a wonderful friend.","persona":"Kabir","source":"inclusion"},
  {"id":"ss-060","cat":"different-wonderful","type":"sort","hook":"Sort: kind about difference, or unkind?","items":[{"id":"a","text":"\"I love your different lunch, can I try?\""},{"id":"b","text":"\"Your food smells weird.\""},{"id":"c","text":"\"Teach me a word in your language!\""},{"id":"d","text":"Laughing at someone's clothes"},{"id":"e","text":"\"Your skin colour is lovely.\""},{"id":"f","text":"Copying how someone talks to tease them"}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Being curious-and-kind about difference beats teasing it.","persona":"any","source":"empathy"},
  {"id":"ss-061","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Everyone should be the same.\"","myth":{"un":"Everyone should look and be the same.","re":"We're all different, and that's exactly right.","why":"Same-inside, different-outside is the truth of people."},"relearn":"We don't all have to be the same; difference is normal and good.","persona":"any","source":"diversity"},
  {"id":"ss-062","cat":"different-wonderful","type":"match","hook":"Same inside! Match each kid to the same feeling.","pairs":[{"left":"A tall kid and a short kid","right":"Both feel happy at play"},{"left":"A girl and a boy","right":"Both feel proud when they try"},{"left":"Kids of every colour","right":"All feel love from family"},{"left":"A new kid and an old friend","right":"Both feel glad to be included"},{"left":"A shy kid and a loud kid","right":"Both want a friend"}],"relearn":"However different outside, we share the same feelings inside.","persona":"any","source":"shared humanity"},
  {"id":"ss-063","cat":"different-wonderful","type":"reflect","hook":"Think of a friend who's different from you.","prompt":"What do you like about them?","options":["They're funny","They're kind","They teach me things","They're my friend"],"affirm":"Their difference is part of why they're great. Difference is wonderful.","relearn":"Differences are reasons to like someone, not avoid them.","persona":"any","source":"friendship"},
  {"id":"ss-064","cat":"different-wonderful","type":"role-play","hook":"Someone teases a friend for looking different.","setup":"Stand up, gently. Say:","yourLine":[{"text":"\"That's not kind. Different is great.\"","best":true},{"text":"Laugh along"}],"relearn":"You can speak up kindly when someone is teased for being different.","persona":"any","source":"bystander / voice"},

  // Fair friends
  {"id":"ss-065","cat":"fair-friends","type":"branch","hook":"\"You can't play with us, you're a girl.\"","options":[{"text":"Say \"that's not fair, anyone can play\"","consequence":"Most kids agree; the game gets bigger and better.","outcome":"fair","best":true},{"text":"Walk away upset","consequence":"You miss out, and the unfair rule stays.","outcome":"missed"}],"debrief":"\"Anyone can play\" is fair, and it makes games more fun.","relearn":"No one should be left out of play for being a girl or boy.","persona":"Aria","source":"fairness / inclusion"},
  {"id":"ss-066","cat":"fair-friends","type":"role-play","hook":"A kid is standing alone, not included.","setup":"Be the one who invites them. Say:","yourLine":[{"text":"\"Come play with us!\"","best":true},{"text":"Ignore them"}],"relearn":"A simple \"come play\" includes someone and makes a friend.","persona":"Kabir","source":"inclusion / voice"},
  {"id":"ss-067","cat":"fair-friends","type":"sort","hook":"Sort: fair friend, or not?","items":[{"id":"a","text":"Lets everyone have a turn"},{"id":"b","text":"Only picks boys for the team"},{"id":"c","text":"Shares the swing"},{"id":"d","text":"Says girls can't join"},{"id":"e","text":"Cheers for the new kid"},{"id":"f","text":"Keeps the ball from one kid"}],"bins":[{"id":"fair","label":"Fair friend","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair friends share and include everyone.","persona":"any","source":"fairness"},
  {"id":"ss-068","cat":"fair-friends","type":"strike-rewrite","hook":"\"Boys and girls can't be friends.\"","myth":{"un":"Boys and girls can't be friends.","re":"Boys and girls make wonderful friends.","why":"Kindness, not gender, makes a friend."},"relearn":"Anyone can be friends with anyone.","persona":"any","source":"friendship"},
  {"id":"ss-069","cat":"fair-friends","type":"match","hook":"Match the fair move to the happy result.","pairs":[{"left":"Everyone gets a turn","right":"Nobody's left out"},{"left":"Pick teams by skill, not gender","right":"Best game ever"},{"left":"Invite the new kid","right":"A new friend"},{"left":"Take turns being leader","right":"Everyone gets to lead"},{"left":"Share the swing","right":"Two happy kids"}],"relearn":"Fair play makes everyone happier.","persona":"any","source":"fairness"},
  {"id":"ss-070","cat":"fair-friends","type":"branch","hook":"Your team is only choosing boys for the running race.","options":[{"text":"Say \"let's pick the fastest, anyone can run\"","consequence":"A fast girl joins and helps the team.","outcome":"fair","best":true},{"text":"Say nothing","consequence":"A great runner is left out for no reason.","outcome":"unfair"}],"debrief":"Pick people for what they can do, not their gender.","relearn":"Anyone can race; fair teams pick on skill.","persona":"Aria","source":"fairness"},
  {"id":"ss-071","cat":"fair-friends","type":"reflect","hook":"Lensy: have you ever felt left out?","prompt":"How did it feel?","options":["Sad","Lonely","Not nice","Yes, I have"],"affirm":"That feeling is why we include everyone. You can be the one who does.","relearn":"Remembering how being left out feels helps us include others.","persona":"any","source":"empathy"},
  {"id":"ss-072","cat":"fair-friends","type":"role-play","hook":"You see a friend being left out for being a girl.","setup":"Back her up. Say:","yourLine":[{"text":"\"She's playing too, that's only fair.\"","best":true},{"text":"Stay quiet"}],"relearn":"Standing up for a left-out friend is a brave, fair thing.","persona":"Aria","source":"bystander / voice"},
  {"id":"ss-073","cat":"fair-friends","type":"sort","hook":"Sort: includes everyone, or leaves out?","items":[{"id":"a","text":"\"Everyone's invited!\""},{"id":"b","text":"\"No girls allowed\""},{"id":"c","text":"\"Come join us\""},{"id":"d","text":"\"Only my group can play\""},{"id":"e","text":"\"There's room for you\""},{"id":"f","text":"\"You can't sit here\""}],"bins":[{"id":"in","label":"Includes everyone","valence":"pos"},{"id":"out","label":"Leaves out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"The best play includes everyone.","persona":"any","source":"inclusion"},
  {"id":"ss-074","cat":"fair-friends","type":"strike-rewrite","hook":"\"Some kids just don't belong.\"","myth":{"un":"Some kids don't belong.","re":"Every kid belongs.","why":"Everyone deserves a place to play and friends."},"relearn":"Every single kid belongs.","persona":"Kabir","source":"belonging"},
  {"id":"ss-075","cat":"fair-friends","type":"build","hook":"Build the rules for a fair playground.","prompt":"Pick the fair rules.","pieces":["everyone can play","take turns","be kind","no leaving people out","boys go first"],"mode":"assemble","key":["everyone can play","take turns","be kind","no leaving people out"],"relearn":"Fair playground rules: everyone plays, take turns, be kind, leave no one out.","persona":"any","source":"fairness"},
  {"id":"ss-076","cat":"fair-friends","type":"reflect","hook":"Lensy: who could YOU include tomorrow?","prompt":"Think of someone.","options":["The new kid","Someone shy","Someone alone","Anyone who wants to play"],"affirm":"That's a kind plan. You can make someone's day with one invite.","relearn":"You can choose to include someone, every day.","persona":"any","source":"prosocial"},

  // Anyone can
  {"id":"ss-077","cat":"anyone-can","type":"strike-rewrite","hook":"\"Only boys can be brave.\"","myth":{"un":"Only boys can be brave.","re":"Bravery is for everyone; girls are brave too.","why":"Brave means trying even when it's scary, anyone can."},"relearn":"Every kid can be brave.","persona":"Aria","source":"courage"},

  // Strong & gentle
  {"id":"ss-078","cat":"strong-gentle","type":"branch","hook":"A boy wants to hug his friend goodbye but worries it's 'not for boys'.","options":[{"text":"Hug him back warmly","consequence":"You both feel happy and close.","outcome":"warm","best":true},{"text":"Tell him hugs aren't for boys","consequence":"He hides his warmth; that's a shame.","outcome":"missed"}],"debrief":"Warmth and hugs are for everyone who wants them.","relearn":"Boys can be warm and affectionate too.","persona":"Faizan-type","source":"emotional health"},

  // Different is wonderful
  {"id":"ss-079","cat":"different-wonderful","type":"role-play","hook":"A friend is shy about their family being different.","setup":"Make them feel proud. Say:","yourLine":[{"text":"\"Your family sounds lovely and special.\"","best":true},{"text":"\"That's weird.\""}],"relearn":"All families are different and good (see My Family Garden).","persona":"any","source":"family diversity (links g03)"},

  // Fair friends
  {"id":"ss-080","cat":"fair-friends","type":"branch","hook":"Capstone: you're picking who plays. The group wants to leave one kid out.","options":[{"text":"Include everyone, fairly","consequence":"The whole group has more fun together.","outcome":"fair","best":true},{"text":"Go with the group and leave them out","consequence":"One kid is sad, and you feel off about it.","outcome":"unfair"}],"debrief":"Including everyone is the fairest, kindest, most fun choice.","relearn":"You can be the one who makes sure everyone belongs.","persona":"any","source":"inclusion"},

  // Different is wonderful
  {"id":"ss-081","cat":"different-wonderful","type":"reflect","hook":"Lensy: same inside, different outside. How does that feel to know?","prompt":"Pick one.","options":["Nice","We're all friends","Cool","Happy"],"affirm":"It's a lovely truth: we're all alike where it counts, and special in our own ways.","relearn":"We're equal inside and wonderfully different outside.","persona":"any","source":"equality"},

  // Anyone can
  {"id":"ss-082","cat":"anyone-can","type":"reflect","hook":"Lensy: what will you carry from today?","prompt":"Pick your motto.","options":["Anyone can play with anything","Different is wonderful","I can be strong and gentle","Everyone belongs"],"affirm":"Carry that everywhere. You're going to make play fair and kind.","relearn":"Toys, colours and dreams are for everyone; difference is wonderful.","persona":"any","source":"consolidation"},
  {"id":"ss-900","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't run fast.\"","myth":{"un":"Girls can't run fast.","re":"Girls can run as fast as anyone; fast legs come from practice.","why":"Running gets quicker the more you practise, not from being a boy."},"relearn":"Anyone can run, race and zoom; practice makes legs fast.","persona":"Aria","source":"physical ability"},
  {"id":"ss-901","cat":"anyone-can","type":"strike-rewrite","hook":"\"Boys can't dance.\"","myth":{"un":"Boys can't dance.","re":"Boys can dance beautifully; dance is for everyone.","why":"Dancing is a skill anyone learns; it has no gender."},"relearn":"Anyone can dance; come join the circle.","persona":"Faizan-type","source":"arts / both-directions"},
  {"id":"ss-902","cat":"anyone-can","type":"strike-rewrite","hook":"\"Cooking is only for mummies.\"","myth":{"un":"Cooking is only for mummies.","re":"Anyone can cook; papas, dadas and kids cook too.","why":"Stirring dal or rolling roti is a skill, and skills are for everyone."},"relearn":"Anyone can cook; it's a lovely skill to grow.","persona":"Faizan-type","source":"occupations / both-directions"},
  {"id":"ss-903","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls aren't good at building.\"","myth":{"un":"Girls aren't good at building.","re":"Girls build great towers and bridges; building grows with practice.","why":"Stacking and fixing get better the more you try, not by gender."},"relearn":"Anyone can build; try, wobble, try again.","persona":"Aria","source":"ability beliefs"},
  {"id":"ss-904","cat":"anyone-can","type":"strike-rewrite","hook":"\"Only didi can plait hair.\"","myth":{"un":"Only didi can plait hair.","re":"A bhaiya can learn to plait his little sister's hair too.","why":"Plaiting is a skill hands learn with practice, not a girls-only job."},"relearn":"Any sibling can learn to plait and help at home.","persona":"Faizan-type","source":"care / both-directions"},
  {"id":"ss-905","cat":"anyone-can","type":"strike-rewrite","hook":"\"Only boys can be pilots.\"","myth":{"un":"Only boys can be pilots.","re":"Anyone can fly a plane one day; India has many women pilots.","why":"Flying needs learning and practice, which any kid can do."},"relearn":"Anyone can be a pilot, driver or astronaut.","persona":"any","source":"occupations"},
  {"id":"ss-906","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't be cricket captains.\"","myth":{"un":"Girls can't be cricket captains.","re":"Girls captain cricket teams too; India has a women's team.","why":"A captain is picked for leading well, not for being a boy."},"relearn":"Anyone can lead the team and call the game.","persona":"Aria","source":"leadership / sport"},
  {"id":"ss-907","cat":"anyone-can","type":"strike-rewrite","hook":"\"Boys can't sing.\"","myth":{"un":"Boys can't sing.","re":"Boys sing wonderfully; singing is for everyone with a voice.","why":"Singing is a skill that grows with practice, not a gender."},"relearn":"Anyone can sing out loud and proud.","persona":"Faizan-type","source":"arts / both-directions"},
  {"id":"ss-908","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't fix things.\"","myth":{"un":"Girls can't fix things.","re":"Girls fix bikes and taps too; fixing is a handy skill to learn.","why":"Fixing comes from trying and practising, not from being a boy."},"relearn":"Anyone can fix and mend; tools are for all hands.","persona":"Aria","source":"skills"},
  {"id":"ss-909","cat":"anyone-can","type":"strike-rewrite","hook":"\"Boys can't draw flowers.\"","myth":{"un":"Boys can't draw flowers.","re":"Boys draw flowers, hearts and rainbows; art is for everyone.","why":"Drawing is a skill anyone grows; no picture belongs to one gender."},"relearn":"Anyone can draw anything they love.","persona":"Faizan-type","source":"arts / both-directions"},
  {"id":"ss-910","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't be police.\"","myth":{"un":"Girls can't be police.","re":"Anyone can be police; India has many brave women officers.","why":"Being police needs courage and care, which any kid can grow."},"relearn":"Anyone can be police, a firefighter or a guard.","persona":"any","source":"occupations"},
  {"id":"ss-911","cat":"anyone-can","type":"strike-rewrite","hook":"\"Boys can't teach little kids.\"","myth":{"un":"Boys can't teach little kids.","re":"Boys can be wonderful teachers; teaching is for everyone.","why":"A good teacher is patient and kind, not a particular gender."},"relearn":"Anyone can teach, help and guide others.","persona":"Faizan-type","source":"occupations / care"},
  {"id":"ss-912","cat":"anyone-can","type":"strike-rewrite","hook":"\"Girls can't swim far.\"","myth":{"un":"Girls can't swim far.","re":"Girls swim long and strong; swimming grows with practice.","why":"More practice means stronger strokes, not being a boy or girl."},"relearn":"Anyone can swim, splash and grow stronger.","persona":"Aria","source":"physical ability"},
  {"id":"ss-913","cat":"anyone-can","type":"role-play","hook":"A boy wants to try cooking in the play kitchen.","setup":"Welcome him in. Say:","yourLine":[{"text":"\"Come cook with us, anyone can!\"","best":true},{"text":"\"Cooking's for girls.\""}],"relearn":"Anyone can cook; it's a lovely skill for everyone.","persona":"Faizan-type","source":"voice / both-directions"},
  {"id":"ss-914","cat":"anyone-can","type":"role-play","hook":"A girl is scared to climb the high bars.","setup":"Cheer her on. Say:","yourLine":[{"text":"\"You can do it, climb up, I'm cheering!\"","best":true},{"text":"\"Climbing's too high for girls.\""}],"relearn":"Anyone can climb; bodies grow strong with practice.","persona":"Aria","source":"voice / physical ability"},
  {"id":"ss-915","cat":"anyone-can","type":"role-play","hook":"A boy wants to join the rangoli drawing.","setup":"Make space for him. Say:","yourLine":[{"text":"\"Come draw rangoli, it's for everyone!\"","best":true},{"text":"\"That's only for girls.\""}],"relearn":"Anyone can make art; rangoli is for all hands.","persona":"Faizan-type","source":"voice / arts"},
  {"id":"ss-916","cat":"anyone-can","type":"role-play","hook":"A girl wants to be the line leader today.","setup":"Speak up for her. Say:","yourLine":[{"text":"\"Let her lead, she'll be a great leader!\"","best":true},{"text":"\"Leaders should be boys.\""}],"relearn":"Anyone can lead; cheering each other helps.","persona":"Aria","source":"voice / leadership"},
  {"id":"ss-917","cat":"anyone-can","type":"role-play","hook":"You want to try a new thing people call 'not for you'.","setup":"Say it brave and slow:","yourLine":[{"text":"\"I can try this. I'd like to learn.\"","best":true},{"text":"\"Maybe it's not for me.\""}],"relearn":"Saying \"I can try\" starts every new skill.","persona":"Kabir","source":"voice / growth mindset"},
  {"id":"ss-918","cat":"anyone-can","type":"role-play","hook":"A boy is teased for wanting to sew a button.","setup":"Stand by him. Say:","yourLine":[{"text":"\"Sewing is a great skill, anyone can!\"","best":true},{"text":"\"Boys don't sew.\""}],"relearn":"Anyone can sew, stitch and mend.","persona":"Faizan-type","source":"voice / skills"},
  {"id":"ss-919","cat":"anyone-can","type":"role-play","hook":"A girl says she'll be the doctor in the pretend game.","setup":"Back her up. Say:","yourLine":[{"text":"\"Yes, you be the doctor, anyone can!\"","best":true},{"text":"\"Girls should be the nurse.\""}],"relearn":"Anyone can be a doctor or a nurse; both are wonderful.","persona":"Aria","source":"voice / occupations"},
  {"id":"ss-920","cat":"anyone-can","type":"role-play","hook":"A boy wants a turn skipping rope with the girls.","setup":"Invite him in. Say:","yourLine":[{"text":"\"Jump in, skipping's for everyone!\"","best":true},{"text":"\"Skipping is a girl game.\""}],"relearn":"Anyone can skip, jump and play.","persona":"Faizan-type","source":"voice / both-directions"},
  {"id":"ss-921","cat":"anyone-can","type":"role-play","hook":"A quiet girl wants to answer but waits to be sure.","setup":"Encourage her voice. Say:","yourLine":[{"text":"\"Say it out loud, your idea matters!\"","best":true},{"text":"\"Better stay quiet and good.\""}],"relearn":"Big voices and good ideas are for every kid.","persona":"Aria","source":"voice / agency"},
  {"id":"ss-922","cat":"anyone-can","type":"role-play","hook":"A boy wants to water the class plants gently.","setup":"Say yes warmly. Say:","yourLine":[{"text":"\"Yes, you take care of them, anyone can!\"","best":true},{"text":"\"Caring jobs are for girls.\""}],"relearn":"Anyone can care for plants and pets.","persona":"Faizan-type","source":"voice / care"},
  {"id":"ss-923","cat":"anyone-can","type":"reflect","hook":"Lensy wonders: what would you love to be one day?","prompt":"Point to a dream.","options":["A doctor","A pilot","A cook","A teacher"],"affirm":"What a lovely dream. Anyone can grow into that.","relearn":"Your dreams aren't fenced in by being a girl or a boy.","persona":"any","source":"aspiration"},
  {"id":"ss-924","cat":"anyone-can","type":"reflect","hook":"Lensy asks: which new thing would you like to try?","prompt":"Pick one to try.","options":["Climb higher","Cook a snack","Lead a game","Sing a song"],"affirm":"You can absolutely try that. Anyone can.","relearn":"Trying new things is for every kid.","persona":"any","source":"growth mindset"},
  {"id":"ss-925","cat":"anyone-can","type":"reflect","hook":"Aria-moment: is it okay for YOU to be the loud, leading one?","prompt":"What do you feel?","options":["Yes!","Maybe","I'd like to try"],"affirm":"Yes it is. Leading and big voices are for you too.","relearn":"Leading and being heard are for every kid.","persona":"Aria","source":"agency"},
  {"id":"ss-926","cat":"anyone-can","type":"reflect","hook":"Lensy asks: what are you proud you can do?","prompt":"Point to one.","options":["Run fast","Help a friend","Make art","Tell a story"],"affirm":"That's wonderful. You can do so many things.","relearn":"Every kid can be proud of what they can do.","persona":"Kabir","source":"self-worth"},
  {"id":"ss-927","cat":"anyone-can","type":"reflect","hook":"Lensy wonders: which job looks fun to you?","prompt":"Pick a job to imagine.","options":["Building bridges","Caring for animals","Flying planes","Cooking in a cafe"],"affirm":"You'd be great at that. Anyone can learn it.","relearn":"Any job is open to any kid; anyone can learn it.","persona":"any","source":"occupations"},
  {"id":"ss-928","cat":"anyone-can","type":"reflect","hook":"Lensy asks: how do you feel when you try something hard?","prompt":"Point to your feeling.","options":["Excited","A bit nervous","Ready to try","Proud after"],"affirm":"All of those are okay. Trying is the brave part.","relearn":"Every kid can be brave and keep trying.","persona":"Aria","source":"courage"},
  {"id":"ss-929","cat":"anyone-can","type":"reflect","hook":"Lensy wonders: what game would you lead today?","prompt":"Choose a game to lead.","options":["Hopscotch","Cricket","Hide-and-seek","Dancing"],"affirm":"Lovely choice. You'd be a great leader.","relearn":"Anyone can be the leader of the game.","persona":"any","source":"leadership"},
  {"id":"ss-930","cat":"anyone-can","type":"reflect","hook":"Lensy asks: what would you like to get better at?","prompt":"Point to one to practise.","options":["Maths","Reading","Drawing","Catching a ball"],"affirm":"Practice makes it grow. You can get better at that.","relearn":"Ability grows with practice, not with being a boy or girl.","persona":"any","source":"growth mindset"},
  {"id":"ss-931","cat":"anyone-can","type":"reflect","hook":"Lensy wonders: who could you cheer on today?","prompt":"Point to one.","options":["A friend climbing","A friend dancing","A friend leading","A friend trying"],"affirm":"Cheering a friend is a kind, lovely thing to do.","relearn":"Cheering each other helps everyone be brave.","persona":"any","source":"inclusion"},
  {"id":"ss-932","cat":"anyone-can","type":"reflect","hook":"Lensy asks: what do you say to yourself before something new?","prompt":"Pick your motto.","options":["I can try","I'll do my best","Mistakes are okay","I'm learning"],"affirm":"That's a wonderful thing to tell yourself.","relearn":"Saying \"I can try\" is the start of every skill.","persona":"Kabir","source":"growth mindset"},
  {"id":"ss-933","cat":"anyone-can","type":"branch","hook":"The boys say a girl can't be goalkeeper.","options":[{"text":"Say \"anyone can be goalie\" and let her try","consequence":"She makes a great save and the team cheers.","outcome":"fair","best":true},{"text":"Tell her to sit out","consequence":"A good goalie is left out for no fair reason."}],"debrief":"Goalies are picked on skill, not on being a boy or girl.","relearn":"Anyone can play any position.","persona":"any","source":"sport / fairness"},
  {"id":"ss-934","cat":"anyone-can","type":"branch","hook":"A boy wants to push the doll pram and friends laugh.","options":[{"text":"Say \"caring is great, push away!\" and join him","consequence":"He smiles and you both care for the dolls together.","outcome":"kind","best":true},{"text":"Laugh along with the others","consequence":"He feels small for doing a kind, caring thing."}],"debrief":"Caring for a baby is a lovely skill for anyone.","relearn":"Anyone can care; care is a strength.","persona":"Faizan-type","source":"care / both-directions"},
  {"id":"ss-935","cat":"anyone-can","type":"branch","hook":"A girl wants to fix the wobbly toy car and someone says it's a boy job.","options":[{"text":"Say \"anyone can fix it\" and hand her the tool","consequence":"She tightens it up and the car rolls again.","outcome":"fair","best":true},{"text":"Take the tool away from her","consequence":"She misses the fun of fixing for no fair reason."}],"debrief":"Fixing is a handy skill anyone can learn.","relearn":"Anyone can fix and mend things.","persona":"Aria","source":"skills"},
  {"id":"ss-936","cat":"anyone-can","type":"branch","hook":"At the school play, a boy wants the dancing role.","options":[{"text":"Say \"you'd dance it beautifully\" and cheer him","consequence":"He dances and everyone claps for him.","outcome":"kind","best":true},{"text":"Tell him boys don't dance","consequence":"He gives up a role he'd have loved."}],"debrief":"Anyone can dance; the stage is for everyone.","relearn":"Boys can dance beautifully; anyone can join in.","persona":"Faizan-type","source":"arts / both-directions"},
  {"id":"ss-937","cat":"anyone-can","type":"branch","hook":"A friend says girls can't do hard maths sums.","options":[{"text":"Say \"maths grows with practice for everyone\"","consequence":"You both try the sum together and crack it.","outcome":"fair","best":true},{"text":"Agree and skip the sum","consequence":"A fun puzzle gets left for a silly reason."}],"debrief":"Maths gets better with practice, not gender.","relearn":"Anyone can be brilliant at maths with practice.","persona":"Aria","source":"ability beliefs"},
  {"id":"ss-938","cat":"anyone-can","type":"branch","hook":"Picking a class monitor, kids say it should be a boy.","options":[{"text":"Say \"anyone can be monitor\" and vote on the fairest kid","consequence":"The kindest, fairest kid gets chosen, girl or boy.","outcome":"fair","best":true},{"text":"Pick a boy because that's the rule","consequence":"A great monitor is skipped for no fair reason."}],"debrief":"A monitor is picked for being fair and kind.","relearn":"Anyone can lead and be the monitor.","persona":"any","source":"leadership"},
  {"id":"ss-939","cat":"anyone-can","type":"branch","hook":"A quiet girl raises her hand but a louder boy talks over her.","options":[{"text":"Say \"let's hear her, she had her hand up\"","consequence":"She shares her idea and it's a great one.","outcome":"fair","best":true},{"text":"Let the loud one keep going","consequence":"Her good idea never gets heard."}],"debrief":"Every kid's voice deserves a turn to be heard.","relearn":"Leading and being heard are for every kid.","persona":"Aria","source":"agency / voice"},
  {"id":"ss-940","cat":"anyone-can","type":"build","hook":"Build a 'jobs anyone can do' board.","prompt":"Add jobs any kid could grow into.","pieces":["doctor","pilot","cook","teacher","builder","vet"],"mode":"assemble","key":["doctor","pilot","cook","teacher","builder","vet"],"relearn":"Any job is open to any kid; anyone can learn it.","persona":"any","source":"occupations"},
  {"id":"ss-941","cat":"anyone-can","type":"build","hook":"Build a 'things I'd love to try' list.","prompt":"Add things anyone can try.","pieces":["climb","cook","lead","dance","sing","fix"],"mode":"assemble","key":["climb","cook","lead","dance","sing","fix"],"relearn":"Your 'can-try' list is as long as you like.","persona":"any","source":"aspiration"},
  {"id":"ss-942","cat":"anyone-can","type":"build","hook":"Build the steps to try something new.","prompt":"Put the brave steps in order.","pieces":["say I can try","take a deep breath","give it a go","practise again"],"mode":"sequence","key":["say I can try","take a deep breath","give it a go","practise again"],"relearn":"Saying \"I can try\" starts every new skill.","persona":"Kabir","source":"growth mindset"},
  {"id":"ss-943","cat":"anyone-can","type":"build","hook":"Build a team where everyone gets a job.","prompt":"Give every kid a role on the team.","pieces":["captain","goalie","striker","cheer leader","coach","helper"],"mode":"assemble","key":["captain","goalie","striker","cheer leader","coach","helper"],"relearn":"Anyone can take any role on the team.","persona":"any","source":"leadership / fairness"},
  {"id":"ss-944","cat":"anyone-can","type":"build","hook":"Build the steps to cook a simple snack.","prompt":"Put the cooking steps in order.","pieces":["wash hands","get the bowl","mix it up","ask a grown-up to help"],"mode":"sequence","key":["wash hands","get the bowl","mix it up","ask a grown-up to help"],"relearn":"Anyone can cook; it's a lovely skill to grow.","persona":"Faizan-type","source":"skills / care"},
  {"id":"ss-945","cat":"anyone-can","type":"build","hook":"Build a 'brave kid' who tries hard things.","prompt":"Pick what makes a brave kid.","pieces":["tries new things","keeps going","asks for help","cheers others"],"mode":"assemble","key":["tries new things","keeps going","asks for help","cheers others"],"relearn":"Every kid can be brave.","persona":"any","source":"courage"},
  {"id":"ss-946","cat":"anyone-can","type":"build","hook":"Build the steps to learn to climb.","prompt":"Put the climbing steps in order.","pieces":["hold tight","find a foothold","pull up slowly","reach the top"],"mode":"sequence","key":["hold tight","find a foothold","pull up slowly","reach the top"],"relearn":"Anyone can climb; bodies grow strong with practice.","persona":"Aria","source":"physical ability"},
  {"id":"ss-947","cat":"anyone-can","type":"match","hook":"Anyone can do these. Match the kid to what they're trying.","pairs":[{"left":"A girl with a football","right":"Scoring a goal"},{"left":"A boy with a whisk","right":"Baking a cake"},{"left":"A girl with a toolbox","right":"Fixing a fan"},{"left":"A boy with a paintbrush","right":"Painting a mural"},{"left":"A kid with a microphone","right":"Singing on stage"}],"relearn":"Anyone can do any of it; the kid isn't picked by the toy.","persona":"any","source":"both-directions"},
  {"id":"ss-948","cat":"anyone-can","type":"match","hook":"Match the grown-up's job to what they do.","pairs":[{"left":"A woman pilot","right":"Flies the plane"},{"left":"A man nurse","right":"Cares for patients"},{"left":"A woman engineer","right":"Builds the bridge"},{"left":"A man teacher","right":"Helps kids learn"},{"left":"A woman farmer","right":"Grows the crops"}],"relearn":"Any job is open to anyone; no job needs a gender.","persona":"any","source":"occupations"},
  {"id":"ss-949","cat":"anyone-can","type":"match","hook":"Match each brave kid to the new thing they tried.","pairs":[{"left":"Tried the high slide","right":"Felt proud after"},{"left":"Spoke up in circle","right":"Shared a great idea"},{"left":"Led the game","right":"Helped everyone play"},{"left":"Tried a hard sum","right":"Got it with practice"},{"left":"Sang a solo","right":"Got a big cheer"}],"relearn":"Every kid can be brave and try new things.","persona":"any","source":"courage / growth mindset"},
  {"id":"ss-950","cat":"anyone-can","type":"sort","hook":"Anyone can, or a silly old rule? Sort it.","items":[{"id":"a","text":"A girl can be team captain"},{"id":"b","text":"Only boys can lead"},{"id":"c","text":"A boy can dance"},{"id":"d","text":"Only girls can dance"},{"id":"e","text":"Anyone can try maths"},{"id":"f","text":"Girls aren't good at maths"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Leading, dancing, maths, anyone can; gender rules are silly.","persona":"any","source":"anyone-can"},
  {"id":"ss-951","cat":"anyone-can","type":"sort","hook":"Sort: anyone can, or a silly old rule?","items":[{"id":"a","text":"A girl can climb high"},{"id":"b","text":"Girls can't climb"},{"id":"c","text":"A boy can cook"},{"id":"d","text":"Boys can't cook"},{"id":"e","text":"Anyone can be brave"},{"id":"f","text":"Only boys are brave"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Climbing, cooking, bravery, anyone can; the rules are silly.","persona":"any","source":"anyone-can"},
  {"id":"ss-952","cat":"anyone-can","type":"sort","hook":"Sort each job: anyone can do it, or a silly rule?","items":[{"id":"a","text":"A woman can be a pilot"},{"id":"b","text":"Only men can be pilots"},{"id":"c","text":"A man can be a nurse"},{"id":"d","text":"Only women can be nurses"},{"id":"e","text":"Anyone can be a teacher"},{"id":"f","text":"Only women can teach"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Pilot, nurse, teacher, anyone can be anything.","persona":"any","source":"occupations"},
  {"id":"ss-953","cat":"anyone-can","type":"sort","hook":"Sort: a fair thing, or a silly old rule?","items":[{"id":"a","text":"A girl gets a turn to lead"},{"id":"b","text":"Only boys get to lead"},{"id":"c","text":"A boy joins the dancing"},{"id":"d","text":"Boys are kept out of dancing"},{"id":"e","text":"Anyone can sing the song"},{"id":"f","text":"Only girls may sing"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"fair","b":"silly","c":"fair","d":"silly","e":"fair","f":"silly"},"relearn":"Everyone gets a turn; leaving someone out for gender is silly.","persona":"any","source":"fairness"},
  {"id":"ss-954","cat":"anyone-can","type":"match","hook":"Match the tool to the kid using it.","pairs":[{"left":"A stethoscope","right":"A girl playing doctor"},{"left":"A cricket bat","right":"A girl at the crease"},{"left":"A ladle","right":"A boy stirring dal"},{"left":"A needle and thread","right":"A boy sewing a button"},{"left":"A microphone","right":"A boy leading the song"}],"relearn":"The tool doesn't pick the kid; anyone can pick up any tool.","persona":"any","source":"both-directions"},
  {"id":"ss-955","cat":"anyone-can","type":"match","hook":"Match each dream to a kid who could grow into it.","pairs":[{"left":"Fly a rocket","right":"A girl loving the sky"},{"left":"Run a kitchen","right":"A boy loving food"},{"left":"Coach a team","right":"A girl loving sport"},{"left":"Care for newborns","right":"A boy loving babies"},{"left":"Build tall buildings","right":"A girl loving blocks"}],"relearn":"Any dream is open to any kid; gender doesn't fence it in.","persona":"any","source":"aspiration"},
  {"id":"ss-956","cat":"anyone-can","type":"match","hook":"Match the action to where it happens.","pairs":[{"left":"Leading the parade","right":"On the school field"},{"left":"Climbing high","right":"At the jungle gym"},{"left":"Cooking a treat","right":"In the kitchen"},{"left":"Dancing freely","right":"On the stage"},{"left":"Fixing a wheel","right":"At the workbench"}],"relearn":"Anyone can do any of these, anywhere; no place is off-limits.","persona":"any","source":"anyone-can"},
  {"id":"ss-957","cat":"anyone-can","type":"sort","hook":"Sort: a thing anyone can grow, or a silly old rule?","items":[{"id":"a","text":"Anyone can get strong with practice"},{"id":"b","text":"Only boys can be strong"},{"id":"c","text":"Anyone can read well in time"},{"id":"d","text":"Girls read, boys can't"},{"id":"e","text":"Anyone can learn to draw"},{"id":"f","text":"Only girls can draw"}],"bins":[{"id":"yes","label":"Anyone can grow it","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Ability grows with practice for every kid, not by gender.","persona":"any","source":"growth mindset"},
  {"id":"ss-958","cat":"anyone-can","type":"sort","hook":"Sort: anyone can join, or a silly old rule?","items":[{"id":"a","text":"A boy can join the dance class"},{"id":"b","text":"Dance class is girls only"},{"id":"c","text":"A girl can join the cricket team"},{"id":"d","text":"Cricket is boys only"},{"id":"e","text":"Anyone can join the choir"},{"id":"f","text":"Choir is for girls only"}],"bins":[{"id":"yes","label":"Anyone can join","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"Any club or team is open to any kid; come join in.","persona":"any","source":"inclusion"},
  {"id":"ss-990","cat":"colours-for-all","type":"strike-rewrite","hook":"Dadi says \"red bangles are only for grown-up ladies, not boys.\"","myth":{"un":"Red is a girl colour.","re":"Red is for everyone; anyone can love red.","why":"A colour is just light and joy, it has no gender."},"relearn":"Every colour is for every kid.","persona":"any","source":"colour & gender"},
  {"id":"ss-991","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Boys shouldn't wear yellow.\"","myth":{"un":"Yellow is not for boys.","re":"Boys can love yellow, like the sun and marigolds.","why":"Bright colours cheer everyone; no colour is off-limits."},"relearn":"No colour belongs to one gender.","persona":"Faizan-type","source":"colour & gender"},
  {"id":"ss-992","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Girls can't wear dark green.\"","myth":{"un":"Dark colours are not for girls.","re":"Any kid can wear dark green or any shade they like.","why":"Light or dark, a colour is a free, happy choice."},"relearn":"Any kid can wear any colour, you choose.","persona":"Aria","source":"autonomy"},
  {"id":"ss-993","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Purple is a princess colour, not for boys.\"","myth":{"un":"Purple is only for girls.","re":"Purple is for everyone; anyone can pick it.","why":"Liking a colour never depends on being a girl or a boy."},"relearn":"Every colour is for every kid.","persona":"Vihaan","source":"colour & gender"},
  {"id":"ss-994","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Baby boys must have blue, never pink.\"","myth":{"un":"Pink is for baby girls, blue for baby boys.","re":"Babies look lovely in any colour their family loves.","why":"That blue-and-pink rule was just a shop idea, not real."},"relearn":"No colour belongs to one gender.","persona":"any","source":"colour & gender history"},
  {"id":"ss-995","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Orange kurta is too bright for a girl.\"","myth":{"un":"Bright orange is not a girl's colour.","re":"A girl can shine in bright orange if she loves it.","why":"Bright is beautiful on any kid that loves it."},"relearn":"Wear your favourite colour proudly.","persona":"Aria","source":"self-esteem"},
  {"id":"ss-996","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Boys can't paint their nails.\"","myth":{"un":"Coloured nails are only for girls.","re":"Anyone can colour their nails for fun.","why":"Painting nails is just play and colour, open to all."},"relearn":"Every colour is for every kid.","persona":"Faizan-type","source":"colour & gender"},
  {"id":"ss-997","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Black is a sad colour, kids shouldn't wear it.\"","myth":{"un":"Black is not for happy little kids.","re":"Black is a cool colour any kid can wear and love.","why":"A colour isn't a feeling; you pick what makes you happy."},"relearn":"Your favourite colour is a happy, free choice.","persona":"any","source":"autonomy"},
  {"id":"ss-998","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Pink shoes? People will laugh at a boy.\"","myth":{"un":"A boy in pink will be laughed at.","re":"A boy can wear pink shoes proudly; good friends cheer.","why":"Kind friends like what you like, not a silly rule."},"relearn":"Wear your favourite colour proudly.","persona":"Faizan-type","source":"self-esteem"},
  {"id":"ss-999","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Holi colours, girls take soft pink, boys take strong blue.\"","myth":{"un":"At Holi boys throw blue, girls throw pink.","re":"At Holi everyone throws every colour together.","why":"Holi is one big mix; all colours fly for all hands."},"relearn":"Every colour is for every kid.","persona":"any","source":"festival / inclusion"},
  {"id":"ss-1000","cat":"colours-for-all","type":"strike-rewrite","hook":"\"That teal water bottle is a girls' one.\"","myth":{"un":"Teal things are for girls only.","re":"A teal bottle is for any kid that likes teal.","why":"A bottle's colour does not pick the kid carrying it."},"relearn":"No colour belongs to one gender.","persona":"Vihaan","source":"colour & gender"},
  {"id":"ss-1001","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Maroon is only for boys' school shoes.\"","myth":{"un":"Maroon is a boy colour.","re":"Maroon is for everyone; any kid can like it.","why":"School colours are shared; no shade is just for boys."},"relearn":"Every colour is for every kid.","persona":"any","source":"colour & gender"},
  {"id":"ss-1002","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Don't pick the pink crayon, it's for the girls.\"","myth":{"un":"The pink crayon is the girls' crayon.","re":"Every crayon in the box is for every kid.","why":"Crayons are to share; colour them all, anyone can."},"relearn":"Every colour is for every kid.","persona":"Vihaan","source":"colour & gender"},
  {"id":"ss-1003","cat":"colours-for-all","type":"strike-rewrite","hook":"\"Lavender kurta is too girly for Diwali.\"","myth":{"un":"Soft lavender is not for boys at a festival.","re":"A boy can wear lavender for Diwali and look great.","why":"Festive dress is a free choice; all colours welcome."},"relearn":"Wear your favourite colour proudly.","persona":"Faizan-type","source":"festival / self-esteem"},
  {"id":"ss-1004","cat":"colours-for-all","type":"build","hook":"Fill a paint tray everyone in class can use.","prompt":"Add colours for the whole class to share.","pieces":["red","pink","blue","green","yellow","purple"],"mode":"assemble","key":["red","pink","blue","green","yellow","purple"],"relearn":"A tray for everyone has all the colours, shared by all.","persona":"any","source":"inclusion"},
  {"id":"ss-1005","cat":"colours-for-all","type":"build","hook":"Pack a colour kit for a Holi morning.","prompt":"Add colours everyone will toss together.","pieces":["pink gulal","blue gulal","green gulal","yellow gulal"],"mode":"assemble","key":["pink gulal","blue gulal","green gulal","yellow gulal"],"relearn":"At Holi every colour is for every hand.","persona":"any","source":"festival / inclusion"},
  {"id":"ss-1006","cat":"colours-for-all","type":"build","hook":"Choose colours for your own birthday kurta.","prompt":"Pick any colours you love for it.","pieces":["pink","teal","orange","silver","green","maroon"],"mode":"assemble","key":["pink","teal","orange","silver","green","maroon"],"relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"autonomy / dress-up"},
  {"id":"ss-1007","cat":"colours-for-all","type":"build","hook":"Decorate a class rangoli everyone helps with.","prompt":"Add colours for all the kids to pour.","pieces":["red","yellow","green","blue","white","pink"],"mode":"assemble","key":["red","yellow","green","blue","white","pink"],"relearn":"A rangoli for everyone uses every colour, shared by all.","persona":"any","source":"festival / inclusion"},
  {"id":"ss-1008","cat":"colours-for-all","type":"build","hook":"Pick the order you'll paint a rainbow, top to bottom.","prompt":"Put the rainbow stripes in order.","pieces":["red on top","then yellow","then green","blue at the bottom"],"mode":"sequence","key":["red on top","then yellow","then green","blue at the bottom"],"relearn":"A rainbow holds every colour, and it's for everyone.","persona":"any","source":"inclusion"},
  {"id":"ss-1009","cat":"colours-for-all","type":"build","hook":"Choose paints for a kite the whole gully will fly.","prompt":"Add colours any kid can pick for their kite.","pieces":["orange","teal","magenta","black","white","brown"],"mode":"assemble","key":["orange","teal","magenta","black","white","brown"],"relearn":"Any kid can choose any colour for their kite.","persona":"any","source":"autonomy"},
  {"id":"ss-1010","cat":"colours-for-all","type":"build","hook":"Fill a dress-up box for everyone at playschool.","prompt":"Add colourful clothes any kid can try.","pieces":["pink dupatta","blue cape","yellow hat","green scarf","red shoes","purple coat"],"mode":"assemble","key":["pink dupatta","blue cape","yellow hat","green scarf","red shoes","purple coat"],"relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"dress-up / inclusion"},
  {"id":"ss-1011","cat":"colours-for-all","type":"build","hook":"Mix two paints to make a brand-new colour.","prompt":"Put the steps in order to make green.","pieces":["take blue","add yellow","stir together","green appears"],"mode":"sequence","key":["take blue","add yellow","stir together","green appears"],"relearn":"Colours mix into more colours, and all are for everyone.","persona":"Vihaan","source":"play / discovery"},
  {"id":"ss-1012","cat":"colours-for-all","type":"build","hook":"Choose bangles for a dress-up game, boys and girls both.","prompt":"Add bangle colours any kid can wear.","pieces":["pink","blue","gold","green","red","silver"],"mode":"assemble","key":["pink","blue","gold","green","red","silver"],"relearn":"Any kid can wear any colour, you choose.","persona":"Faizan-type","source":"dress-up / autonomy"},
  {"id":"ss-1013","cat":"colours-for-all","type":"sort","hook":"Sort: true, or a silly old rule?","items":[{"id":"a","text":"Anyone can love yellow"},{"id":"b","text":"Pink is only for girls"},{"id":"c","text":"Any kid can wear green"},{"id":"d","text":"Boys can't like purple"},{"id":"e","text":"Everyone can enjoy orange"},{"id":"f","text":"Red is only for boys"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"Anyone can like any colour; a rule that bans one is silly.","persona":"Vihaan","source":"colour & gender"},
  {"id":"ss-1014","cat":"colours-for-all","type":"sort","hook":"Who can wear each colour? Sort them.","items":[{"id":"a","text":"Pink, for anyone"},{"id":"b","text":"Blue, boys only"},{"id":"c","text":"Teal, for anyone"},{"id":"d","text":"Maroon, boys only"},{"id":"e","text":"Lavender, for anyone"},{"id":"f","text":"Gold, girls only"}],"bins":[{"id":"all","label":"For anyone","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"all","b":"silly","c":"all","d":"silly","e":"all","f":"silly"},"relearn":"Every colour is for every kid.","persona":"any","source":"colour & gender"},
  {"id":"ss-1015","cat":"colours-for-all","type":"sort","hook":"Holi colours, sort the kind idea from the silly rule.","items":[{"id":"a","text":"Everyone throws every colour"},{"id":"b","text":"Pink is just for girls"},{"id":"c","text":"Boys and girls share the gulal"},{"id":"d","text":"Blue is just for boys"},{"id":"e","text":"All hands play together"},{"id":"f","text":"Girls can't use green"}],"bins":[{"id":"kind","label":"Fair idea","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"kind","b":"silly","c":"kind","d":"silly","e":"kind","f":"silly"},"relearn":"At Holi every colour is for every hand.","persona":"any","source":"festival / inclusion"},
  {"id":"ss-1016","cat":"colours-for-all","type":"sort","hook":"Sort what's true about colours.","items":[{"id":"a","text":"You choose your favourite colour"},{"id":"b","text":"A colour can be 'wrong' for you"},{"id":"c","text":"All colours are for all kids"},{"id":"d","text":"Some colours are off-limits to boys"},{"id":"e","text":"Liking a colour is free and happy"},{"id":"f","text":"Girls must pick soft colours"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"Your favourite colour is a happy, free choice.","persona":"any","source":"autonomy"},
  {"id":"ss-1017","cat":"colours-for-all","type":"sort","hook":"Sort the crayons by who can use them.","items":[{"id":"a","text":"Yellow, for anyone"},{"id":"b","text":"Pink, girls only"},{"id":"c","text":"Green, for anyone"},{"id":"d","text":"Blue, boys only"},{"id":"e","text":"Purple, for anyone"},{"id":"f","text":"Brown, boys only"}],"bins":[{"id":"all","label":"For anyone","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"all","b":"silly","c":"all","d":"silly","e":"all","f":"silly"},"relearn":"Every crayon is for every kid.","persona":"any","source":"colour & gender"},
  {"id":"ss-1018","cat":"colours-for-all","type":"sort","hook":"Cheer or silly rule? Sort what people said.","items":[{"id":"a","text":"\"Love your pink shirt!\""},{"id":"b","text":"\"Pink isn't for boys.\""},{"id":"c","text":"\"Cool green shoes!\""},{"id":"d","text":"\"Boys can't wear that.\""},{"id":"e","text":"\"Your colour suits you!\""},{"id":"f","text":"\"Change it, it's a girl colour.\""}],"bins":[{"id":"kind","label":"Kind cheer","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"kind","b":"silly","c":"kind","d":"silly","e":"kind","f":"silly"},"relearn":"You can cheer a friend for wearing any colour he loves.","persona":"Faizan-type","source":"voice / support"},
  {"id":"ss-1019","cat":"colours-for-all","type":"sort","hook":"Sort the dress-up clothes, who can wear them?","items":[{"id":"a","text":"Pink cape, for anyone"},{"id":"b","text":"Blue hat, boys only"},{"id":"c","text":"Yellow scarf, for anyone"},{"id":"d","text":"Red dupatta, girls only"},{"id":"e","text":"Green coat, for anyone"},{"id":"f","text":"Purple shoes, girls only"}],"bins":[{"id":"all","label":"For anyone","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"all","b":"silly","c":"all","d":"silly","e":"all","f":"silly"},"relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"dress-up / autonomy"},
  {"id":"ss-1020","cat":"colours-for-all","type":"sort","hook":"Sort the rainbow facts.","items":[{"id":"a","text":"A rainbow has every colour"},{"id":"b","text":"Some rainbow colours are 'boy' ones"},{"id":"c","text":"Everyone can love a rainbow"},{"id":"d","text":"Girls can't like the blue stripe"},{"id":"e","text":"All stripes are for all kids"},{"id":"f","text":"Boys can't like the pink stripe"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"A rainbow holds every colour, and it's for everyone.","persona":"any","source":"inclusion"},
  {"id":"ss-1021","cat":"colours-for-all","type":"sort","hook":"Free choice or silly rule? Sort each one.","items":[{"id":"a","text":"Pick the colour you love"},{"id":"b","text":"Wear what your gender 'should'"},{"id":"c","text":"Try a new colour anytime"},{"id":"d","text":"Only pink for girls"},{"id":"e","text":"Mix lots of colours"},{"id":"f","text":"Only blue for boys"}],"bins":[{"id":"free","label":"Free choice","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"free","b":"silly","c":"free","d":"silly","e":"free","f":"silly"},"relearn":"Your favourite colour is a happy, free choice.","persona":"Aria","source":"autonomy"},
  {"id":"ss-1022","cat":"colours-for-all","type":"role-play","hook":"A cousin says your blue bangles are 'only for girls.'","setup":"You love them. Say:","yourLine":[{"text":"\"I love blue, and colours are for everyone.\"","best":true},{"text":"\"Okay, I'll take them off.\""}],"relearn":"No colour belongs to one gender.","persona":"Vihaan","source":"voice / autonomy"},
  {"id":"ss-1023","cat":"colours-for-all","type":"role-play","hook":"A shopkeeper says \"pink section is for your sister, not you.\"","setup":"You want the pink one. Say:","yourLine":[{"text":"\"I'd like the pink one, please. It's my favourite.\"","best":true},{"text":"\"Oh, then give me a blue one.\""}],"relearn":"Wear your favourite colour proudly.","persona":"Faizan-type","source":"voice / self-esteem"},
  {"id":"ss-1024","cat":"colours-for-all","type":"role-play","hook":"A friend in a pink shirt got teased.","setup":"Stand by your friend. Say:","yourLine":[{"text":"\"Pink looks great on you. Colours are for everyone.\"","best":true},{"text":"\"Maybe wear blue tomorrow.\""}],"relearn":"You can cheer a friend for wearing any colour he loves.","persona":"any","source":"voice / support"},
  {"id":"ss-1025","cat":"colours-for-all","type":"role-play","hook":"A teacher hands you a 'boy colour' for your drawing.","setup":"You wanted a different one. Say:","yourLine":[{"text":"\"May I use purple instead? I love it.\"","best":true},{"text":"\"Fine, I'll just use this one.\""}],"relearn":"Any kid can choose any colour they like.","persona":"Aria","source":"voice / autonomy"},
  {"id":"ss-1026","cat":"colours-for-all","type":"role-play","hook":"At Holi someone says \"pink gulal is for the girls only.\"","setup":"You want to play with pink too. Say:","yourLine":[{"text":"\"Pink's for everyone, let's all play!\"","best":true},{"text":"\"Okay, I'll only use blue.\""}],"relearn":"At Holi every colour is for every hand.","persona":"any","source":"festival / voice"},
  {"id":"ss-1027","cat":"colours-for-all","type":"role-play","hook":"Your brother says yellow nail colour is 'silly for a boy.'","setup":"You like it on your nails. Say:","yourLine":[{"text":"\"I like yellow, and it's just a fun colour.\"","best":true},{"text":"\"You're right, I'll wipe it off.\""}],"relearn":"Wear your favourite colour proudly.","persona":"Faizan-type","source":"voice / self-esteem"},
  {"id":"ss-1028","cat":"colours-for-all","type":"role-play","hook":"A kid says \"that green tiffin is a boy's, give it back.\"","setup":"It's the colour you picked. Say:","yourLine":[{"text":"\"I chose green because I love it. Green's for anyone.\"","best":true},{"text":"\"Sorry, I'll get a pink one.\""}],"relearn":"No colour belongs to one gender.","persona":"Aria","source":"voice / autonomy"},
  {"id":"ss-1029","cat":"colours-for-all","type":"role-play","hook":"Auntie says \"choose a softer colour, that bright one's for boys.\"","setup":"You love the bright one. Say:","yourLine":[{"text":"\"I love this bright colour, it's perfect for me.\"","best":true},{"text":"\"Alright, I'll pick a soft one.\""}],"relearn":"Wear your favourite colour proudly.","persona":"Aria","source":"voice / self-esteem"},
  {"id":"ss-1030","cat":"colours-for-all","type":"role-play","hook":"A friend asks which crayon you want from the shared box.","setup":"The pink one is your favourite. Say:","yourLine":[{"text":"\"The pink, please. It's my favourite colour.\"","best":true},{"text":"\"Um, you pick one for me.\""}],"relearn":"Every crayon is for every kid.","persona":"Vihaan","source":"voice / autonomy"},
  {"id":"ss-1031","cat":"colours-for-all","type":"match","hook":"Match each kid to the colour they happily chose.","pairs":[{"left":"Vihaan picked pink","right":"Pink balloon"},{"left":"Aria picked black","right":"Black cap"},{"left":"Kabir picked green","right":"Green kite"},{"left":"Megha's son picked purple","right":"Purple shoes"},{"left":"A friend picked rainbow","right":"Rainbow flag"}],"relearn":"When kids pick their own colours, everyone's happy.","persona":"any","source":"autonomy"},
  {"id":"ss-1032","cat":"colours-for-all","type":"match","hook":"Match the festival to a colour kids of all kinds enjoy.","pairs":[{"left":"Holi","right":"Pink gulal"},{"left":"Diwali","right":"Golden lamps"},{"left":"Pongal","right":"Yellow rangoli"},{"left":"Eid","right":"Green bangles"},{"left":"Onam","right":"Red flowers"}],"relearn":"Every festival colour is for every kid.","persona":"any","source":"festival / inclusion"},
  {"id":"ss-1033","cat":"colours-for-all","type":"match","hook":"Match each thing to a colour, any kid can have it.","pairs":[{"left":"Water bottle","right":"Teal"},{"left":"School bag","right":"Maroon"},{"left":"Cap","right":"Yellow"},{"left":"Slippers","right":"Pink"},{"left":"Umbrella","right":"Green"}],"relearn":"Any kid can choose any colour for their things.","persona":"any","source":"autonomy"},
  {"id":"ss-1034","cat":"colours-for-all","type":"match","hook":"Match the kind cheer to the colour a friend wore.","pairs":[{"left":"\"Cool shirt!\"","right":"Pink shirt"},{"left":"\"Nice clip!\"","right":"Blue clip"},{"left":"\"Wow, bright!\"","right":"Orange kurta"},{"left":"\"Lovely shoes!\"","right":"Purple shoes"},{"left":"\"Sunny bag!\"","right":"Yellow bag"}],"relearn":"You can cheer a friend for any colour he loves.","persona":"Faizan-type","source":"voice / support"},
  {"id":"ss-1035","cat":"colours-for-all","type":"match","hook":"Mix two paints, match them to the colour they make.","pairs":[{"left":"Blue and yellow","right":"Green"},{"left":"Red and white","right":"Pink"},{"left":"Red and blue","right":"Purple"},{"left":"Red and yellow","right":"Orange"},{"left":"All the paints","right":"Brown"}],"relearn":"Colours mix into more colours, all for everyone.","persona":"Vihaan","source":"play / discovery"},
  {"id":"ss-1036","cat":"colours-for-all","type":"match","hook":"Match each kid to the colour they happily wear.","pairs":[{"left":"A cheerful boy","right":"Pink shirt"},{"left":"A bold girl","right":"Dark blue"},{"left":"A playful kid","right":"Rainbow tee"},{"left":"A calm boy","right":"Lavender"},{"left":"A bright girl","right":"Bright red"}],"relearn":"No colour belongs to one gender; all kids look great.","persona":"any","source":"colour & gender"},
  {"id":"ss-1037","cat":"colours-for-all","type":"match","hook":"Match the dress-up item to a colour any kid can pick.","pairs":[{"left":"Cape","right":"Purple"},{"left":"Hat","right":"Blue"},{"left":"Scarf","right":"Pink"},{"left":"Shoes","right":"Green"},{"left":"Belt","right":"Gold"}],"relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"dress-up / autonomy"},
  {"id":"ss-1038","cat":"colours-for-all","type":"branch","hook":"You love a yellow dress, but a kid says yellow is 'for boys.'","options":[{"text":"Wear it proudly and say yellow's for everyone","consequence":"You keep what you love; the silly rule fades.","outcome":"fair","best":true},{"text":"Hide it and pick a 'girl colour'","consequence":"You give up a colour you love for a silly rule.","outcome":"missed"}],"debrief":"Wear your favourite colour proudly.","relearn":"No colour belongs to one gender.","persona":"Aria","source":"peer norms"},
  {"id":"ss-1039","cat":"colours-for-all","type":"branch","hook":"At the shop, only one pink cycle is left and your friend wants blue.","options":[{"text":"Take the pink you love; he takes the blue he loves","consequence":"Both get a colour you each chose; both happy.","outcome":"fair","best":true},{"text":"Swap so you match 'the right gender'","consequence":"You both end up with colours you didn't pick.","outcome":"missed"}],"debrief":"Your favourite colour is a happy, free choice.","relearn":"Any kid can choose any colour they like.","persona":"Vihaan","source":"autonomy"},
  {"id":"ss-1040","cat":"colours-for-all","type":"branch","hook":"A friend in a pink kurta is being teased at the party.","options":[{"text":"Tell them pink suits him and colours are for all","consequence":"Your friend feels proud; the teasing stops.","outcome":"kind","best":true},{"text":"Stay quiet so you're not teased too","consequence":"Your friend feels alone with the teasing.","outcome":"missed"}],"debrief":"You can cheer a friend for any colour he loves.","relearn":"You can cheer a friend for wearing any colour he loves.","persona":"Faizan-type","source":"support / voice"},
  {"id":"ss-1041","cat":"colours-for-all","type":"branch","hook":"Painting time: the teacher splits 'pink table for girls, blue for boys.'","options":[{"text":"Ask if anyone can use any colour","consequence":"Everyone shares all the paints and has fun.","outcome":"fair","best":true},{"text":"Sit where your gender 'should'","consequence":"Kids miss out on colours they really wanted.","outcome":"missed"}],"debrief":"Every colour is for every kid; share them all.","relearn":"Every colour is for every kid.","persona":"any","source":"inclusion"},
  {"id":"ss-1042","cat":"colours-for-all","type":"branch","hook":"You want green mehndi cones; someone says green's 'a boy thing.'","options":[{"text":"Pick green because you love it","consequence":"You enjoy the colour you really wanted.","outcome":"fair","best":true},{"text":"Pick a different colour to fit in","consequence":"You give up a colour you love for a silly rule.","outcome":"missed"}],"debrief":"Any kid can choose any colour they like.","relearn":"No colour belongs to one gender.","persona":"Aria","source":"autonomy"},
  {"id":"ss-1043","cat":"colours-for-all","type":"branch","hook":"Your little brother wants the pink umbrella; dadi reaches for blue.","options":[{"text":"Say pink is fine and hand him the pink one","consequence":"He gets the colour he loves and beams.","outcome":"kind","best":true},{"text":"Give him blue so it's a 'boy colour'","consequence":"He carries a colour he didn't want.","outcome":"missed"}],"debrief":"No colour belongs to one gender.","relearn":"No colour belongs to one gender.","persona":"any","source":"family / autonomy"},
  {"id":"ss-1044","cat":"colours-for-all","type":"branch","hook":"New kid joins art class and grabs the 'wrong colour' for her gender.","options":[{"text":"Smile and say any colour is welcome here","consequence":"She feels included and keeps her favourite.","outcome":"kind","best":true},{"text":"Tell her that colour isn't for girls","consequence":"She feels unwelcome on her first day.","outcome":"missed"}],"debrief":"Every colour is for every kid; welcome them all.","relearn":"Every colour is for every kid.","persona":"any","source":"inclusion"},
  {"id":"ss-1045","cat":"colours-for-all","type":"reflect","hook":"Lensy wonders: which colour do YOU love most today?","prompt":"Point to it.","options":["Pink","Blue","Green","A mix!"],"affirm":"That's your colour, and it's a wonderful choice. Every colour is for you.","relearn":"Your favourite colour is a happy, free choice.","persona":"any","source":"autonomy"},
  {"id":"ss-1046","cat":"colours-for-all","type":"reflect","hook":"Lensy asks: what colour would your dream kurta be?","prompt":"Show the one you'd wear.","options":["Bright orange","Soft lavender","Deep maroon","Sunny yellow"],"affirm":"You'd look lovely in that. Any kid can wear any colour they love.","relearn":"Any kid can wear any colour, you choose.","persona":"any","source":"dress-up / autonomy"},
  {"id":"ss-1047","cat":"colours-for-all","type":"reflect","hook":"Lensy asks: which colour would you toss first at Holi?","prompt":"Pick your colour.","options":["Pink","Yellow","Green","All of them!"],"affirm":"Fun choice! At Holi every colour is for every hand.","relearn":"At Holi every colour is for every hand.","persona":"any","source":"festival / autonomy"},
  {"id":"ss-1048","cat":"colours-for-all","type":"reflect","hook":"Lensy wonders: what colour is your happiest one?","prompt":"Point to it.","options":["Red","Purple","Teal","A rainbow!"],"affirm":"That colour suits you perfectly. No colour is off-limits.","relearn":"Your favourite colour is a happy, free choice.","persona":"any","source":"autonomy"},
  {"id":"ss-1049","cat":"colours-for-all","type":"reflect","hook":"Lensy asks: which colour would you paint your room?","prompt":"Choose your colour.","options":["Sky blue","Bright pink","Leaf green","Many colours!"],"affirm":"What a happy room that would be. Any colour is for you.","relearn":"Any kid can choose any colour they like.","persona":"any","source":"autonomy"},
  {"id":"ss-1050","cat":"colours-for-all","type":"reflect","hook":"Lensy asks: what colour kite would you fly?","prompt":"Show your kite colour.","options":["Pink","Blue","Yellow","A patterned one!"],"affirm":"That kite would soar. Any kid can pick any colour they love.","relearn":"Any kid can choose any colour they like.","persona":"any","source":"autonomy"},
  {"id":"ss-1051","cat":"colours-for-all","type":"reflect","hook":"Lensy wonders: which colour makes you feel proud?","prompt":"Point to your proud colour.","options":["Gold","Maroon","Bright green","A colour I mix!"],"affirm":"Wear it proudly! Your favourite colour is yours to love.","relearn":"Wear your favourite colour proudly.","persona":"any","source":"self-esteem"},
  {"id":"ss-1080","cat":"different-wonderful","type":"sort","hook":"Same inside, different outside. Where does each one go?","items":[{"id":"a","text":"We all feel happy when we play"},{"id":"b","text":"Our hair is curly, straight or wavy"},{"id":"c","text":"We all get hungry at lunch"},{"id":"d","text":"We speak many home languages"},{"id":"e","text":"Every heart goes thump-thump"},{"id":"f","text":"Our eyes are many lovely colours"}],"bins":[{"id":"same","label":"Same inside","valence":"pos"},{"id":"diff","label":"Different outside (and good!)","valence":"neutral"}],"key":{"a":"same","b":"diff","c":"same","d":"diff","e":"same","f":"diff"},"relearn":"Inside we're alike; outside we're wonderfully different.","persona":"any","source":"equality / diversity"},
  {"id":"ss-1081","cat":"different-wonderful","type":"sort","hook":"Sort these into kind words and unkind words about skin.","items":[{"id":"a","text":"\"Your brown skin glows!\""},{"id":"b","text":"\"You're too dark.\""},{"id":"c","text":"\"Every shade is lovely.\""},{"id":"d","text":"\"Fair skin is prettier.\""},{"id":"e","text":"\"I love your skin colour.\""},{"id":"f","text":"\"Stay out of the sun or you'll go dark.\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"kind","b":"silly","c":"kind","d":"silly","e":"kind","f":"silly"},"relearn":"Every skin colour is beautiful; no shade is 'better'.","persona":"any","source":"India colourism"},
  {"id":"ss-1082","cat":"different-wonderful","type":"sort","hook":"A new friend is different from you. Sort: kind, or unkind?","items":[{"id":"a","text":"\"Teach me to count in your language!\""},{"id":"b","text":"\"Why do you talk funny?\""},{"id":"c","text":"\"I like your festival sweets.\""},{"id":"d","text":"Copying how they speak to tease them"},{"id":"e","text":"\"Sit with us, come on!\""},{"id":"f","text":"Pointing and giggling at their clothes"}],"bins":[{"id":"kind","label":"Curious & kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Being curious-and-kind about difference beats teasing it.","persona":"Kabir","source":"empathy"},
  {"id":"ss-1083","cat":"different-wonderful","type":"sort","hook":"Sort: wonderful about us, or a silly old rule?","items":[{"id":"a","text":"We come in many heights"},{"id":"b","text":"Tall kids beat short kids"},{"id":"c","text":"Some wear glasses, some don't"},{"id":"d","text":"Be friends only with look-alikes"},{"id":"e","text":"Families come in many shapes"},{"id":"f","text":"There's one 'right' way to look"}],"bins":[{"id":"good","label":"Wonderful & true","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"good","b":"silly","c":"good","d":"silly","e":"good","f":"silly"},"relearn":"Difference is normal and good; no one look is 'right'.","persona":"any","source":"diversity"},
  {"id":"ss-1084","cat":"different-wonderful","type":"sort","hook":"Sort: same feeling inside, or different outside?","items":[{"id":"a","text":"Both miss home on day one"},{"id":"b","text":"One is tall, one is small"},{"id":"c","text":"Both feel proud when they finish"},{"id":"d","text":"One has freckles, one has none"},{"id":"e","text":"Both giggle at the same joke"},{"id":"f","text":"One has a turban, one a topknot"}],"bins":[{"id":"same","label":"Same feeling inside","valence":"pos"},{"id":"diff","label":"Different outside","valence":"neutral"}],"key":{"a":"same","b":"diff","c":"same","d":"diff","e":"same","f":"diff"},"relearn":"However different outside, we share the same feelings inside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1085","cat":"different-wonderful","type":"sort","hook":"Sort: a reason to like a friend, or a silly reason to avoid?","items":[{"id":"a","text":"They know stories from far away"},{"id":"b","text":"Their skin is a different shade"},{"id":"c","text":"They eat new food"},{"id":"d","text":"They pray a different way"},{"id":"e","text":"They taught you a game"},{"id":"f","text":"They look different"}],"bins":[{"id":"like","label":"Like them!","valence":"pos"},{"id":"silly","label":"Silly to avoid","valence":"neg"}],"key":{"a":"like","b":"silly","c":"like","d":"silly","e":"like","f":"silly"},"relearn":"Differences are reasons to like someone, not to avoid them.","persona":"any","source":"friendship"},
  {"id":"ss-1086","cat":"different-wonderful","type":"sort","hook":"Sort: everyone belongs, or someone's left out?","items":[{"id":"a","text":"The new kid gets a buddy"},{"id":"b","text":"\"You can't sit here, you're new.\""},{"id":"c","text":"We learn 'hello' in three tongues"},{"id":"d","text":"Only look-alikes share crayons"},{"id":"e","text":"Everyone's drawing is on the wall"},{"id":"f","text":"One kid's lunch is mocked"}],"bins":[{"id":"belong","label":"Everyone belongs","valence":"pos"},{"id":"out","label":"Someone left out","valence":"neg"}],"key":{"a":"belong","b":"out","c":"belong","d":"out","e":"belong","f":"out"},"relearn":"A real class is wonderfully different; every kid belongs.","persona":"any","source":"inclusion"},
  {"id":"ss-1087","cat":"different-wonderful","type":"sort","hook":"Sort: true about families, or a silly old rule?","items":[{"id":"a","text":"One parent is a real family"},{"id":"b","text":"Only big families count"},{"id":"c","text":"Living with grandparents is lovely"},{"id":"d","text":"A family must look one way"},{"id":"e","text":"Two homes is okay"},{"id":"f","text":"Different families can't be happy"}],"bins":[{"id":"good","label":"All families, good","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"good","b":"silly","c":"good","d":"silly","e":"good","f":"silly"},"relearn":"All families are different and good (see My Family Garden).","persona":"any","source":"family diversity (links g03)"},
  {"id":"ss-1088","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Dark skin should be hidden from the sun.\"","myth":{"un":"Dark skin is something to hide away.","re":"Every skin colour is lovely and meant to be seen.","why":"Skin protects us and comes in many beautiful shades."},"relearn":"No shade of skin is 'better'; every one is beautiful.","persona":"any","source":"India colourism"},
  {"id":"ss-1089","cat":"different-wonderful","type":"strike-rewrite","hook":"\"You can only be friends with kids who look like you.\"","myth":{"un":"You can only be friends with kids who look like you.","re":"A different-looking kid can be a wonderful friend.","why":"Kindness makes a friend, not matching faces."},"relearn":"A different-looking kid can be a wonderful friend.","persona":"any","source":"friendship"},
  {"id":"ss-1090","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Speaking another language at home is wrong.\"","myth":{"un":"Speaking another language at home is wrong.","re":"Every home language is a treasure to be proud of.","why":"Each language is a new way to say hello to the world."},"relearn":"Different languages add colour to the world.","persona":"any","source":"diversity"},
  {"id":"ss-1091","cat":"different-wonderful","type":"strike-rewrite","hook":"\"It's bad to be the only one who looks like you.\"","myth":{"un":"It's bad to be the only one who looks like you.","re":"Being one of a kind is something to feel proud of.","why":"Nobody else is exactly you, and that's a gift."},"relearn":"Your differences make you, you, and that's a gift.","persona":"any","source":"self-esteem"},
  {"id":"ss-1092","cat":"different-wonderful","type":"strike-rewrite","hook":"\"We should all eat the same food.\"","myth":{"un":"Everyone should eat the same food.","re":"Different foods mean so many yummy tastes to share.","why":"Trying a friend's food is a happy adventure."},"relearn":"Our differences add colour to the world.","persona":"Kabir","source":"diversity"},
  {"id":"ss-1093","cat":"different-wonderful","type":"strike-rewrite","hook":"\"A kid who learns slower doesn't belong.\"","myth":{"un":"A kid who learns slower doesn't belong with us.","re":"Every kid belongs, learning fast or slow.","why":"We all learn in our own time and at our own pace."},"relearn":"Every kid belongs; we don't all have to be the same.","persona":"Kabir","source":"belonging"},
  {"id":"ss-1094","cat":"different-wonderful","type":"strike-rewrite","hook":"\"A kid in a wheelchair can't really play.\"","myth":{"un":"A kid in a wheelchair can't really play with us.","re":"They can play lots of games, just their own way.","why":"There's a way to include everyone in the fun."},"relearn":"Every kid belongs, and there's a way to include everyone.","persona":"any","source":"inclusion"},
  {"id":"ss-1095","cat":"different-wonderful","type":"strike-rewrite","hook":"\"We're not really the same inside.\"","myth":{"un":"Kids who look different aren't the same inside.","re":"Inside, we all have a beating heart and big feelings.","why":"Where it counts, all of us are alike."},"relearn":"Equal inside, wonderfully different outside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1096","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Looking different is something to fix.\"","myth":{"un":"Looking different is something to fix.","re":"There's nothing to fix; different is wonderful as it is.","why":"A world where everyone matched would be so dull."},"relearn":"Different is wonderful, not wrong.","persona":"any","source":"diversity"},
  {"id":"ss-1097","cat":"different-wonderful","type":"strike-rewrite","hook":"\"Curly hair is messy hair.\"","myth":{"un":"Curly hair is messy hair.","re":"Curly, straight, wavy, every kind of hair is lovely.","why":"Hair comes in many beautiful kinds, all just right."},"relearn":"Different is wonderful; there's no one 'right' way to look.","persona":"any","source":"self-esteem"},
  {"id":"ss-1098","cat":"different-wonderful","type":"strike-rewrite","hook":"\"A new kid from far away will never fit in.\"","myth":{"un":"A new kid from far away will never fit in.","re":"A new friend brings new stories, and soon belongs.","why":"One kind hello is all it takes to begin."},"relearn":"Every kid belongs; difference is the start of something good.","persona":"any","source":"belonging"},
  {"id":"ss-1099","cat":"different-wonderful","type":"match","hook":"Match the difference to why it's lovely.","pairs":[{"left":"Many skin shades","right":"Like a box of warm colours"},{"left":"Many home languages","right":"So many ways to say hello"},{"left":"Many kinds of hair","right":"Curls, waves and straight, all lovely"},{"left":"Many favourite foods","right":"So many yummy tastes to share"},{"left":"Many family shapes","right":"So many homes full of love"}],"relearn":"Our differences add colour to the world.","persona":"any","source":"diversity"},
  {"id":"ss-1100","cat":"different-wonderful","type":"match","hook":"Same inside! Match each pair of kids to the feeling they share.","pairs":[{"left":"A shy kid and a loud kid","right":"Both want a friend"},{"left":"A new kid and an old friend","right":"Both feel happy included"},{"left":"A tall kid and a small kid","right":"Both feel proud to try"},{"left":"Kids of every skin colour","right":"All feel family love"},{"left":"A fast and a slow learner","right":"Both feel glad to get it"}],"relearn":"However different outside, we share the same feelings inside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1101","cat":"different-wonderful","type":"match","hook":"Match each kid to the special thing they bring to the class.","pairs":[{"left":"A kid from another state","right":"A new song to teach"},{"left":"A kid fond of painting","right":"Bright pictures for the wall"},{"left":"A kid with three languages","right":"Three ways to say morning"},{"left":"A kid keen on cricket","right":"A game all can join"},{"left":"A kid with a big laugh","right":"Giggles that spread around"}],"relearn":"Every kid brings something wonderful; difference is a gift.","persona":"any","source":"belonging"},
  {"id":"ss-1102","cat":"different-wonderful","type":"match","hook":"Match the kind words to the friend who needs them.","pairs":[{"left":"Teased for dark skin","right":"\"Your skin is beautiful.\""},{"left":"New kid sitting alone","right":"\"Come sit with us!\""},{"left":"Shy about their food","right":"\"Can I try? It smells yummy.\""},{"left":"Mocked for their accent","right":"\"I love how you say that.\""},{"left":"Worried they're different","right":"\"Different is wonderful.\""}],"relearn":"You can speak up kindly when someone is teased for being different.","persona":"any","source":"empathy / bystander"},
  {"id":"ss-1103","cat":"different-wonderful","type":"match","hook":"We're alike where it counts. Match the body part to what it does for all of us.","pairs":[{"left":"Your heart","right":"Goes thump-thump in every chest"},{"left":"Your tummy","right":"Gets hungry for everyone"},{"left":"Your eyes","right":"Cry happy and sad tears for all"},{"left":"Your hands","right":"Wave hello in every home"},{"left":"Your smile","right":"Means joy in every language"}],"relearn":"Inside we're alike, however different we look outside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1104","cat":"different-wonderful","type":"match","hook":"Match each greeting to the language it comes from. So many ways to say hi!","pairs":[{"left":"Namaste","right":"Hindi hello"},{"left":"Vanakkam","right":"Tamil hello"},{"left":"Sat sri akal","right":"Punjabi hello"},{"left":"Nomoshkar","right":"Bengali hello"},{"left":"Kem cho","right":"Gujarati hello"}],"relearn":"Different languages are so many lovely ways to say hello.","persona":"any","source":"diversity"},
  {"id":"ss-1105","cat":"different-wonderful","type":"match","hook":"Match the festival to the family who loves it. All different, all lovely.","pairs":[{"left":"Diwali lamps","right":"A family lighting diyas"},{"left":"Eid sweets","right":"A family sharing sevaiyan"},{"left":"Christmas star","right":"A family by the tree"},{"left":"Pongal pot","right":"A family with the harvest"},{"left":"Baisakhi dhol","right":"A family dancing bhangra"}],"relearn":"All families are different and good, with their own joys.","persona":"any","source":"family diversity (links g03)"},
  {"id":"ss-1106","cat":"different-wonderful","type":"build","hook":"Build a 'We Belong' wall for a wonderfully different class.","prompt":"Add things that say everyone belongs.","pieces":["all skin tones","every home language","a wheelchair ramp","big smiles","\"You belong here\""],"mode":"assemble","key":["all skin tones","every home language","a wheelchair ramp","big smiles","\"You belong here\""],"relearn":"A real class is wonderfully different, and every kid belongs.","persona":"any","source":"inclusion"},
  {"id":"ss-1107","cat":"different-wonderful","type":"build","hook":"Build a 'Same Inside' poster of what we all share.","prompt":"Add the things every kid has inside.","pieces":["a beating heart","big feelings","a need for friends","dreams to chase","love from family"],"mode":"assemble","key":["a beating heart","big feelings","a need for friends","dreams to chase","love from family"],"relearn":"Equal inside, wonderfully different outside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1108","cat":"different-wonderful","type":"build","hook":"Build a rainbow of skin tones, every shade lovely.","prompt":"Add the skin shades for your class picture.","pieces":["wheat","honey","caramel","deep brown","rich cocoa","warm tan"],"mode":"assemble","key":["wheat","honey","caramel","deep brown","rich cocoa","warm tan"],"relearn":"All skin colours are lovely; no shade is 'better'.","persona":"any","source":"India colourism"},
  {"id":"ss-1109","cat":"different-wonderful","type":"build","hook":"Build a 'Hello Around India' chart to welcome every kid.","prompt":"Add ways to say hello.","pieces":["Namaste","Vanakkam","Sat sri akal","Nomoshkar","Kem cho","Adaab"],"mode":"assemble","key":["Namaste","Vanakkam","Sat sri akal","Nomoshkar","Kem cho","Adaab"],"relearn":"So many languages, so many lovely ways to say hello.","persona":"any","source":"diversity"},
  {"id":"ss-1110","cat":"different-wonderful","type":"build","hook":"Build a welcome plan for a new kid who's far from home.","prompt":"Put the kind steps in order.","pieces":["smile and say hello","tell them your name","show them where to sit","ask them to play","teach each other a word"],"mode":"sequence","key":["smile and say hello","tell them your name","show them where to sit","ask them to play","teach each other a word"],"relearn":"A kind welcome turns a different kid into a wonderful friend.","persona":"any","source":"belonging"},
  {"id":"ss-1111","cat":"different-wonderful","type":"build","hook":"Build a 'Curious & Kind' kit for meeting someone new.","prompt":"Pick the curious, kind things to do.","pieces":["ask a friendly question","listen well","share something of yours","say what you like about them","find what you both enjoy"],"mode":"assemble","key":["ask a friendly question","listen well","share something of yours","say what you like about them","find what you both enjoy"],"relearn":"Being curious-and-kind about difference beats teasing it.","persona":"any","source":"empathy"},
  {"id":"ss-1112","cat":"different-wonderful","type":"build","hook":"Build a 'World Lunch' table where every food is welcome.","prompt":"Add lunches from many homes.","pieces":["idli","roti and dal","momos","poha","fish curry","dhokla"],"mode":"assemble","key":["idli","roti and dal","momos","poha","fish curry","dhokla"],"relearn":"Different foods mean so many yummy tastes to share.","persona":"any","source":"diversity"},
  {"id":"ss-1113","cat":"different-wonderful","type":"reflect","hook":"Lensy: what's one thing that makes YOU special?","prompt":"Point to one.","options":["My freckles","My big laugh","My curly hair","The way I say things"],"affirm":"That's a wonderful part of you. Nobody else is just like you.","relearn":"Your differences make you, you, and that's a gift.","persona":"any","source":"self-esteem"},
  {"id":"ss-1114","cat":"different-wonderful","type":"reflect","hook":"Lensy: think of your favourite skin colour to draw with.","prompt":"Which warm shade do you like?","options":["A rich cocoa","A deep brown","A honey colour","A golden tan"],"affirm":"Every shade you picked is beautiful, just like every real skin.","relearn":"All skin colours are lovely; no shade is 'better'.","persona":"any","source":"India colourism"},
  {"id":"ss-1115","cat":"different-wonderful","type":"reflect","hook":"Lensy: what new thing could a different friend teach you?","prompt":"Point to one you'd love.","options":["A word in their language","A game from their home","A song they know","A food to try"],"affirm":"How lovely! Their difference is a gift you both get to share.","relearn":"Differences are reasons to like someone, not avoid them.","persona":"any","source":"friendship"},
  {"id":"ss-1116","cat":"different-wonderful","type":"reflect","hook":"Lensy: how does it feel that we're all the same inside?","prompt":"Pick one.","options":["Cosy","Like we're all friends","Happy","Safe"],"affirm":"It's a lovely truth: alike where it counts, special in our own ways.","relearn":"We're equal inside and wonderfully different outside.","persona":"any","source":"equality"},
  {"id":"ss-1139","cat":"different-wonderful","type":"reflect","hook":"Lensy: think of a friend whose home is different from yours.","prompt":"What do you like to do there?","options":["Eat their food","Hear their stories","Play their games","Meet their family"],"affirm":"How nice! Different homes are full of lovely things to share.","relearn":"All families are different and good.","persona":"any","source":"family diversity (links g03)"},
  {"id":"ss-1117","cat":"different-wonderful","type":"reflect","hook":"Lensy: what could you say to welcome a brand-new kid?","prompt":"Point to a kind hello.","options":["\"Hi, I'm so glad you're here!\"","\"Want to play with me?\"","\"What's your name?\"","\"Come sit by me!\""],"affirm":"Any of those is a lovely welcome. A kind hello makes a friend.","relearn":"A kind welcome helps every kid belong.","persona":"any","source":"belonging"},
  {"id":"ss-1118","cat":"different-wonderful","type":"reflect","hook":"Lensy: what do you and a different friend BOTH feel?","prompt":"Point to a feeling you share.","options":["Happy at play","Proud when we try","Sad when we're left out","Love from family"],"affirm":"Yes! However different outside, you feel the same things inside.","relearn":"However different outside, we share the same feelings inside.","persona":"any","source":"shared humanity"},
  {"id":"ss-1119","cat":"different-wonderful","type":"reflect","hook":"Lensy: which 'hello' would be fun to learn next?","prompt":"Point to one.","options":["Vanakkam","Namaste","Adaab","Sat sri akal"],"affirm":"Lovely pick! Each one is a new way to greet a friend.","relearn":"Different languages are lovely ways to say hello.","persona":"any","source":"diversity"},
  {"id":"ss-1121","cat":"different-wonderful","type":"reflect","hook":"Lensy: who is someone different from you that you're glad to know?","prompt":"Think of them.","options":["A new classmate","A neighbour","A cousin far away","A friend who moved here"],"affirm":"They make your world bigger and brighter. Difference is wonderful.","relearn":"Differences are reasons to like someone, not avoid them.","persona":"any","source":"friendship"},
  {"id":"ss-1122","cat":"different-wonderful","type":"reflect","hook":"Lensy: what could you do if a friend is teased for being different?","prompt":"Point to a kind plan.","options":["Stand by them","Say \"that's not kind\"","Ask them to play with me","Tell a grown-up"],"affirm":"That's brave and kind. Standing up helps everyone feel they belong.","relearn":"You can speak up kindly when someone is teased for being different.","persona":"any","source":"bystander"},
  {"id":"ss-1123","cat":"different-wonderful","type":"reflect","hook":"Lensy: what makes your family special and lovely?","prompt":"Point to one.","options":["Our food","Our festivals","Who lives with us","Our funny words"],"affirm":"That's wonderful. Every family is different, and every one is good.","relearn":"All families are different and good.","persona":"any","source":"family diversity (links g03)"},
  {"id":"ss-1124","cat":"different-wonderful","type":"branch","hook":"A kid is teased for having very dark skin and looks sad.","options":[{"text":"Say \"your skin is beautiful, just like mine\"","consequence":"They smile; the unkind words lose their sting.","outcome":"kind","best":true},{"text":"Stay quiet so you don't get teased too","consequence":"They feel alone, and the teasing carries on."}],"debrief":"Every skin colour is beautiful; a kind word can mend a hard moment.","relearn":"No shade of skin is 'better'; speaking up kindly helps.","persona":"any","source":"India colourism / bystander"},
  {"id":"ss-1125","cat":"different-wonderful","type":"branch","hook":"A new kid eats lunch from a different home and others wrinkle their noses.","options":[{"text":"Say \"that smells nice, can I try a bite?\"","consequence":"They beam, and soon everyone's swapping food.","outcome":"kind","best":true},{"text":"Wrinkle your nose too","consequence":"They hide their lunch and feel left out."}],"debrief":"Different food is a yummy adventure, not a reason to tease.","relearn":"Being curious-and-kind about difference beats teasing it.","persona":"any","source":"empathy"},
  {"id":"ss-1126","cat":"different-wonderful","type":"branch","hook":"A kid who uses a wheelchair wants to join your circle game.","options":[{"text":"Make space and find a way they can play too","consequence":"Everyone has fun; the game is even better.","outcome":"fair","best":true},{"text":"Say the game's not for them","consequence":"They're left out, and that's not fair or kind."}],"debrief":"There's always a way to include everyone in the fun.","relearn":"Every kid belongs, and there's a way to include everyone.","persona":"any","source":"inclusion"},
  {"id":"ss-1127","cat":"different-wonderful","type":"branch","hook":"A friend speaks a different home language and a kid mocks how they talk.","options":[{"text":"Say \"I love that language, teach me a word!\"","consequence":"Your friend feels proud; the mocking stops.","outcome":"kind","best":true},{"text":"Giggle along with the mocking","consequence":"Your friend goes quiet and feels small."}],"debrief":"Every language is a treasure, not something to laugh at.","relearn":"Different languages add colour to the world.","persona":"any","source":"diversity / bystander"},
  {"id":"ss-1128","cat":"different-wonderful","type":"branch","hook":"A new kid from far away is standing alone at break.","options":[{"text":"Walk over and say \"come play, I'll show you around\"","consequence":"They light up; you've made a new friend.","outcome":"kind","best":true},{"text":"Leave them, since they're new and different","consequence":"They stay lonely, and you both miss out."}],"debrief":"One kind hello turns a different kid into a wonderful friend.","relearn":"A kid different from you can be a wonderful friend.","persona":"any","source":"belonging"},
  {"id":"ss-1129","cat":"different-wonderful","type":"branch","hook":"A friend is shy because their family looks different from the others.","options":[{"text":"Say \"your family sounds wonderful, tell me more\"","consequence":"They glow with pride and share happily.","outcome":"warm","best":true},{"text":"Say their family is strange","consequence":"They feel ashamed of something good."}],"debrief":"All families are different and good; pride beats a silly rule.","relearn":"All families are different and good.","persona":"any","source":"family diversity (links g03)"},
  {"id":"ss-1130","cat":"different-wonderful","type":"branch","hook":"Kids are picking only friends who look like them and one child is left out.","options":[{"text":"Say \"we look different and that's great, join us\"","consequence":"The group grows and play gets more fun.","outcome":"fair","best":true},{"text":"Go along with the look-alike group","consequence":"A nice kid is left out for no real reason."}],"debrief":"Differences are reasons to like someone, not to leave them out.","relearn":"Differences are reasons to like someone, not avoid them.","persona":"any","source":"friendship"},
  {"id":"ss-1131","cat":"different-wonderful","type":"role-play","hook":"A friend says they wish their skin were lighter.","setup":"Cheer them up. Say:","yourLine":[{"text":"\"Your skin is beautiful exactly as it is.\"","best":true},{"text":"\"Maybe try staying out of the sun.\""}],"relearn":"Every skin colour is beautiful; no shade is 'better'.","persona":"any","source":"India colourism / voice"},
  {"id":"ss-1132","cat":"different-wonderful","type":"role-play","hook":"A new kid from far away is shy to say hello.","setup":"Make them feel welcome. Say:","yourLine":[{"text":"\"Hi! I'm glad you're here. Come play with us.\"","best":true},{"text":"\"You're not from here, are you?\""}],"relearn":"A kind welcome helps a different kid feel they belong.","persona":"Kabir","source":"belonging / voice"},
  {"id":"ss-1133","cat":"different-wonderful","type":"role-play","hook":"A friend is shy about the language they speak at home.","setup":"Help them feel proud. Say:","yourLine":[{"text":"\"Your language is lovely, will you teach me a word?\"","best":true},{"text":"\"Just speak normally.\""}],"relearn":"Every home language is a treasure to be proud of.","persona":"any","source":"diversity / voice"},
  {"id":"ss-1134","cat":"different-wonderful","type":"role-play","hook":"Someone laughs at a friend's different lunch.","setup":"Stand up kindly. Say:","yourLine":[{"text":"\"That smells delicious. Different food is the best!\"","best":true},{"text":"\"Yeah, it's a bit weird.\""}],"relearn":"You can speak up kindly when someone is teased for being different.","persona":"any","source":"empathy / voice"},
  {"id":"ss-1135","cat":"different-wonderful","type":"role-play","hook":"A friend worries they don't fit in because they look different.","setup":"Remind them what's true. Say:","yourLine":[{"text":"\"You fit in just right. Different is wonderful!\"","best":true},{"text":"\"Maybe try to look like everyone else.\""}],"relearn":"Different is wonderful; everyone belongs.","persona":"any","source":"belonging / voice"},
  {"id":"ss-1136","cat":"different-wonderful","type":"role-play","hook":"A friend is teased for using a hearing aid.","setup":"Back them up gently. Say:","yourLine":[{"text":"\"That helps you hear, that's cool. Be kind!\"","best":true},{"text":"Laugh along with the others"}],"relearn":"Every kid belongs; speaking up kindly helps everyone.","persona":"any","source":"inclusion / voice"},
  {"id":"ss-1137","cat":"different-wonderful","type":"role-play","hook":"A friend feels odd being the only kid with their kind of family.","setup":"Make them feel proud. Say:","yourLine":[{"text":"\"Your family sounds lovely. All families are good.\"","best":true},{"text":"\"That is a bit strange.\""}],"relearn":"All families are different and good.","persona":"any","source":"family diversity (links g03) / voice"},
  {"id":"ss-1138","cat":"different-wonderful","type":"role-play","hook":"A friend says \"we're so different, we can't be friends.\"","setup":"Tell them what's true. Say:","yourLine":[{"text":"\"We're different outside, but friends inside!\"","best":true},{"text":"\"You're right, let's not.\""}],"relearn":"A kid different from you can be a wonderful friend.","persona":"any","source":"friendship / voice"},
  {"id":"ss-1140","cat":"different-wonderful","type":"match","hook":"Match the wonderful difference to the friend who has it.","pairs":[{"left":"Loves spicy dosa","right":"A friend from the south"},{"left":"Speaks Bengali at home","right":"A friend from the east"},{"left":"Wears a bright phiran","right":"A friend from the hills"},{"left":"Dances the garba","right":"A friend from the west"},{"left":"Knows desert folk tales","right":"A friend from the sands"}],"relearn":"Our differences add colour to the world; each friend is a gift.","persona":"any","source":"diversity"},
  {"id":"ss-1170","cat":"fair-friends","type":"branch","hook":"Kids tell a girl she can't join the cricket gully match.","options":[{"text":"Say \"she bats well, let her play too\"","consequence":"She joins, hits a four, and the match is more fun.","outcome":"fair","best":true},{"text":"Say \"yeah, cricket's for boys\"","consequence":"A good batter is left out and the gully feels smaller.","outcome":"unfair"}],"debrief":"Anyone can play cricket; fair friends judge the bat, not the gender.","relearn":"No one should be left out of play for being a girl or a boy.","persona":"Vihaan","source":"fairness / inclusion"},
  {"id":"ss-1171","cat":"fair-friends","type":"branch","hook":"A new boy who speaks Tamil just joined and stands alone at lunch.","options":[{"text":"Wave him over and share your tiffin","consequence":"He grins, shares his too, and you both laugh.","outcome":"fair","best":true},{"text":"Whisper that he talks funny","consequence":"He feels alone and eats by himself, sad.","outcome":"unkind"}],"debrief":"A simple \"come sit\" turns a stranger into a friend.","relearn":"A simple \"come play\" includes someone and makes a friend.","persona":"any","source":"inclusion / belonging"},
  {"id":"ss-1172","cat":"fair-friends","type":"branch","hook":"Your group is building a fort and someone says \"no girls in the fort.\"","options":[{"text":"Say \"it's everyone's fort, she can build too\"","consequence":"More hands make a bigger, better fort for all.","outcome":"fair","best":true},{"text":"Agree and keep building without her","consequence":"She's shut out, and the fort feels unfriendly.","outcome":"unfair"}],"debrief":"The best play includes everyone, so all the kids belong.","relearn":"Fair friends share and include everyone.","persona":"Aria","source":"fairness / inclusion"},
  {"id":"ss-1173","cat":"fair-friends","type":"branch","hook":"Two kids both want to be the captain of the kho-kho team.","options":[{"text":"Say \"let's take turns being captain\"","consequence":"Both get a turn to lead and nobody's upset.","outcome":"fair","best":true},{"text":"Say \"only the boy gets to be captain\"","consequence":"One kid never gets to lead, and that's not fair.","outcome":"unfair"}],"debrief":"Anyone can lead; taking turns is the fair way to share it.","relearn":"Every single kid belongs and gets a fair turn.","persona":"any","source":"fairness / leadership"},
  {"id":"ss-1174","cat":"fair-friends","type":"branch","hook":"A friend in a wheelchair wants to join the circle game.","options":[{"text":"Make the circle bigger so she fits in","consequence":"She joins easily and the circle game goes on.","outcome":"fair","best":true},{"text":"Say the circle's already full","consequence":"She's left outside, watching, feeling left out.","outcome":"unkind"}],"debrief":"We can change the game a little so everyone belongs.","relearn":"Every single kid belongs; we make room for everyone.","persona":"Kabir","source":"belonging / inclusion"},
  {"id":"ss-1175","cat":"fair-friends","type":"branch","hook":"Kids are picking teams for relay and keep choosing only their own friends.","options":[{"text":"Say \"let's count off so teams are mixed and fair\"","consequence":"Teams get mixed, and new kids get picked too.","outcome":"fair","best":true},{"text":"Let the same kids always get left for last","consequence":"The same few feel unwanted every single time.","outcome":"unfair"}],"debrief":"Fair teams mix everyone in, not just your own gang.","relearn":"Fair teams pick fairly, so no one is always left out.","persona":"any","source":"fairness / teams"},
  {"id":"ss-1176","cat":"fair-friends","type":"branch","hook":"At the festival, a boy wants to join the girls' rangoli circle.","options":[{"text":"Hand him some chalk and say \"join in!\"","consequence":"He adds bright dots and the rangoli looks lovely.","outcome":"fair","best":true},{"text":"Say \"rangoli isn't for boys\"","consequence":"He walks off, and a happy circle loses a friend.","outcome":"unfair"}],"debrief":"Anyone can make rangoli; everyone is welcome in the circle.","relearn":"Anyone can be friends with anyone; everyone may join.","persona":"Faizan-type","source":"inclusion / both-directions"},
  {"id":"ss-1177","cat":"fair-friends","type":"branch","hook":"Your best friend won't play with a kid because his clothes are old.","options":[{"text":"Say \"he's fun to play with, come on\"","consequence":"They play together and your friend has fun too.","outcome":"fair","best":true},{"text":"Go along and leave the kid out","consequence":"A kind kid is shut out for no real reason.","outcome":"unkind"}],"debrief":"What a friend is like inside matters, not their clothes.","relearn":"Every single kid belongs; we don't leave anyone out.","persona":"any","source":"belonging / equal-inside"},
  {"id":"ss-1178","cat":"fair-friends","type":"branch","hook":"Too many kids want the skipping rope, and someone says \"girls, step out.\"","options":[{"text":"Say \"let's all take turns instead\"","consequence":"Everyone gets a turn and no one is pushed out.","outcome":"fair","best":true},{"text":"Tell the girls to wait at the side","consequence":"Half the kids never get a turn, just for being girls.","outcome":"unfair"}],"debrief":"Taking turns is fair; pushing girls or boys out is not.","relearn":"No one should be left out of play for being a girl or a boy.","persona":"Aria","source":"fairness"},
  {"id":"ss-1179","cat":"fair-friends","type":"branch","hook":"A quiet new girl asks if she can join your game of pakda-pakdi.","options":[{"text":"Smile and say \"yes, you're the catcher first!\"","consequence":"She lights up, plays hard, and makes new friends.","outcome":"fair","best":true},{"text":"Say \"we don't know you\" and run off","consequence":"She stands alone again, wishing she'd been asked in.","outcome":"unkind"}],"debrief":"You don't have to know someone to say \"come play.\"","relearn":"A simple \"come play\" includes someone and makes a friend.","persona":"any","source":"inclusion / belonging"},
  {"id":"ss-1180","cat":"fair-friends","type":"branch","hook":"Boys say the football is theirs and girls can only watch.","options":[{"text":"Say \"the ground is for everyone, let's all play\"","consequence":"Girls and boys play together and it's a great match.","outcome":"fair","best":true},{"text":"Keep the ball away from the girls","consequence":"Girls who love football never get to kick it.","outcome":"unfair"}],"debrief":"The playground belongs to every kid, to share.","relearn":"Anyone can race or play; fair teams leave no one out.","persona":"Vihaan","source":"fairness / shared-space"},
  {"id":"ss-1181","cat":"fair-friends","type":"branch","hook":"At a birthday, kids split into \"boys' games\" and \"girls' games.\"","options":[{"text":"Say \"let's all play one big game together\"","consequence":"Everyone joins one game and the party is more fun.","outcome":"fair","best":true},{"text":"Stay split and tease whoever crosses over","consequence":"Kids who'd mix get teased, so friends stay apart.","outcome":"unkind"}],"debrief":"Boys and girls playing together makes the best party.","relearn":"Boys and girls make wonderful friends and play together.","persona":"any","source":"friendship / inclusion"},
  {"id":"ss-1182","cat":"fair-friends","type":"role-play","hook":"A friend is teased for being too slow to be picked for the team.","setup":"Stick up for him. Say:","yourLine":[{"text":"\"He's on my team, and we're glad to have him.\"","best":true},{"text":"Laugh along with the teasing"}],"relearn":"Standing up for a left-out friend is a brave, fair thing.","persona":"Aria","source":"bystander / voice"},
  {"id":"ss-1183","cat":"fair-friends","type":"role-play","hook":"A boy near you is sitting out because kids said dancing is only for girls.","setup":"Invite him in. Say:","yourLine":[{"text":"\"Come dance with us, anyone can!\"","best":true},{"text":"Tell him to just go sit down"}],"relearn":"Anyone can dance and join; fair friends include everyone.","persona":"Faizan-type","source":"inclusion / both-directions"},
  {"id":"ss-1184","cat":"fair-friends","type":"role-play","hook":"You notice a child eating lunch alone every day in the corner.","setup":"Walk over and say:","yourLine":[{"text":"\"Want to sit with us today?\"","best":true},{"text":"Walk past and say nothing"}],"relearn":"A simple invite includes someone and makes a friend.","persona":"Kabir","source":"inclusion / voice"},
  {"id":"ss-1185","cat":"fair-friends","type":"role-play","hook":"Kids tell your cousin she can't climb the slide because she's small.","setup":"Help her join. Say:","yourLine":[{"text":"\"She can have a turn too, let's make space.\"","best":true},{"text":"Say \"yeah, you wait at the back\""}],"relearn":"Every kid gets a fair turn; we make room for everyone.","persona":"any","source":"fairness / turn-taking"},
  {"id":"ss-1186","cat":"fair-friends","type":"role-play","hook":"A friend says \"don't play with him, he's from a different colony.\"","setup":"Choose kindness out loud. Say:","yourLine":[{"text":"\"He's nice, and everyone can play with us.\"","best":true},{"text":"Agree and leave the boy out"}],"relearn":"Every single kid belongs, wherever they're from.","persona":"any","source":"belonging / voice"},
  {"id":"ss-1187","cat":"fair-friends","type":"role-play","hook":"Two of your friends are fighting over who gets the only cricket bat.","setup":"Help them be fair. Say:","yourLine":[{"text":"\"Let's take turns, one over each.\"","best":true},{"text":"Grab the bat for yourself"}],"relearn":"Sharing and taking turns is how fair friends play.","persona":"Vihaan","source":"fairness / sharing"},
  {"id":"ss-1188","cat":"fair-friends","type":"role-play","hook":"A girl asks to join the carrom game and a boy starts to say no.","setup":"Open the game up. Say:","yourLine":[{"text":"\"Sure, you can be my partner!\"","best":true},{"text":"Say \"only us four are playing\""}],"relearn":"Anyone can play carrom; fair friends welcome everyone.","persona":"any","source":"inclusion / voice"},
  {"id":"ss-1189","cat":"fair-friends","type":"role-play","hook":"Your little brother is left out because he's younger than the others.","setup":"Bring him in. Say:","yourLine":[{"text":"\"He can be on my team, come on bhai.\"","best":true},{"text":"Tell him to go play alone"}],"relearn":"Fair friends leave no one out, big or small.","persona":"any","source":"belonging / family"},
  {"id":"ss-1190","cat":"fair-friends","type":"sort","hook":"Sort each play move: fair friend, or not fair?","items":[{"id":"a","text":"Lets the new kid have a turn"},{"id":"b","text":"Says \"no girls on our team\""},{"id":"c","text":"Shares the slide with everyone"},{"id":"d","text":"Picks only friends, leaves others out"},{"id":"e","text":"Cheers when a quiet kid joins"},{"id":"f","text":"Hides the ball so one kid can't play"}],"bins":[{"id":"fair","label":"Fair friend","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair friends share and include everyone.","persona":"any","source":"fairness"},
  {"id":"ss-1191","cat":"fair-friends","type":"sort","hook":"Sort what kids say: includes everyone, or leaves out?","items":[{"id":"a","text":"\"Everyone's invited!\""},{"id":"b","text":"\"No boys allowed here\""},{"id":"c","text":"\"Come join our game\""},{"id":"d","text":"\"You're not in our group\""},{"id":"e","text":"\"There's room for one more\""},{"id":"f","text":"\"Girls can only watch\""}],"bins":[{"id":"in","label":"Includes everyone","valence":"pos"},{"id":"out","label":"Leaves out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"The best play includes everyone, leaving no one out.","persona":"any","source":"inclusion"},
  {"id":"ss-1192","cat":"fair-friends","type":"sort","hook":"Sort each way to pick a team: fair pick, or silly old rule?","items":[{"id":"a","text":"Pick the fast runner"},{"id":"b","text":"Pick only boys, never girls"},{"id":"c","text":"Take turns choosing for everyone"},{"id":"d","text":"Leave out a kid you don't know"},{"id":"e","text":"Pick the best thrower"},{"id":"f","text":"Say girls aren't good enough"}],"bins":[{"id":"fair","label":"Fair pick","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"fair","b":"silly","c":"fair","d":"silly","e":"fair","f":"silly"},"relearn":"Fair teams pick on skill, not on gender.","persona":"any","source":"fairness / teams"},
  {"id":"ss-1193","cat":"fair-friends","type":"sort","hook":"Sort each move at the park: kind friend, or unkind?","items":[{"id":"a","text":"Asks the shy kid to join"},{"id":"b","text":"Laughs at how a kid talks"},{"id":"c","text":"Helps a small kid up the steps"},{"id":"d","text":"Calls a kid names to keep them out"},{"id":"e","text":"Saves a turn for the waiting kid"},{"id":"f","text":"Pushes ahead and skips the line"}],"bins":[{"id":"kind","label":"Kind friend","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Kind friends include and help; unkind moves push kids out.","persona":"any","source":"kindness"},
  {"id":"ss-1194","cat":"fair-friends","type":"sort","hook":"Sort these playground rules: a fair rule, or not fair?","items":[{"id":"a","text":"Everyone gets a turn"},{"id":"b","text":"Boys go before girls"},{"id":"c","text":"Be kind to whoever joins"},{"id":"d","text":"Only our gang can play"},{"id":"e","text":"Leave no one out"},{"id":"f","text":"New kids must wait all day"}],"bins":[{"id":"fair","label":"Fair rule","valence":"pos"},{"id":"unfair","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Fair rules: everyone plays, take turns, leave no one out.","persona":"any","source":"fairness / rules"},
  {"id":"ss-1195","cat":"fair-friends","type":"sort","hook":"Sort each thing a friend does: makes friends, or breaks friends?","items":[{"id":"a","text":"Shares the swing turn by turn"},{"id":"b","text":"Tells secrets to keep one kid out"},{"id":"c","text":"Says sorry after a bump"},{"id":"d","text":"Teases a kid for being different"},{"id":"e","text":"Cheers for the other team too"},{"id":"f","text":"Won't let a girl be the leader"}],"bins":[{"id":"make","label":"Makes friends","valence":"pos"},{"id":"break","label":"Breaks friends","valence":"neg"}],"key":{"a":"make","b":"break","c":"make","d":"break","e":"make","f":"break"},"relearn":"Sharing and including make friends; leaving out breaks them.","persona":"any","source":"friendship"},
  {"id":"ss-1226","cat":"fair-friends","type":"sort","hook":"A friend is teased. Sort each move: stands up, or joins in?","items":[{"id":"a","text":"\"Stop, that's not kind\""},{"id":"b","text":"Laughs along with the teasing"},{"id":"c","text":"\"Come play with me instead\""},{"id":"d","text":"Copies the mean nickname"},{"id":"e","text":"Tells a grown-up to help"},{"id":"f","text":"Joins in calling the name"}],"bins":[{"id":"up","label":"Stands up","valence":"tell"},{"id":"in","label":"Joins in","valence":"neg"}],"key":{"a":"up","b":"in","c":"up","d":"in","e":"up","f":"in"},"relearn":"Standing up for a teased friend is brave and fair.","persona":"Aria","source":"bystander / kindness"},
  {"id":"ss-1227","cat":"fair-friends","type":"sort","hook":"Sort each one: true that everyone belongs, or a silly old rule?","items":[{"id":"a","text":"Every kid can play"},{"id":"b","text":"Boys and girls can't be friends"},{"id":"c","text":"Anyone can join our game"},{"id":"d","text":"New kids must wait outside"},{"id":"e","text":"Different kids belong too"},{"id":"f","text":"Only our colony's kids play"}],"bins":[{"id":"true","label":"True for everyone","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"Every single kid belongs; the rest are silly old rules.","persona":"any","source":"belonging"},
  {"id":"ss-1196","cat":"fair-friends","type":"strike-rewrite","hook":"\"Girls slow the game down, don't pick them.\"","myth":{"un":"Girls slow the game down.","re":"Girls play just as well; pick on skill, not gender.","why":"How fast you play comes from practice, not from being a girl or a boy."},"relearn":"Fair teams pick on skill, so girls and boys both belong.","persona":"any","source":"fairness / ability"},
  {"id":"ss-1197","cat":"fair-friends","type":"strike-rewrite","hook":"\"The new kid should sit out till we know them.\"","myth":{"un":"New kids should sit out.","re":"New kids can join right away.","why":"You make a friend by playing together, not by waiting."},"relearn":"A simple \"come play\" includes someone and makes a friend.","persona":"Kabir","source":"inclusion / belonging"},
  {"id":"ss-1198","cat":"fair-friends","type":"strike-rewrite","hook":"\"Boys and girls can't be on the same team.\"","myth":{"un":"Boys and girls can't be on the same team.","re":"Boys and girls make a great team together.","why":"A team is stronger when every kid gets to join in."},"relearn":"Anyone can be friends and teammates with anyone.","persona":"any","source":"friendship / teams"},
  {"id":"ss-1199","cat":"fair-friends","type":"strike-rewrite","hook":"\"That kid is different, so leave them out.\"","myth":{"un":"Different kids should be left out.","re":"Different kids belong just as much as you.","why":"Being different is wonderful, and every kid deserves a friend."},"relearn":"Every single kid belongs, however different they are.","persona":"any","source":"belonging / equal-inside"},
  {"id":"ss-1200","cat":"fair-friends","type":"strike-rewrite","hook":"\"It's okay to leave one kid out if everyone else agrees.\"","myth":{"un":"It's okay to leave one kid out.","re":"Leaving a kid out isn't fair, even if the group agrees.","why":"A whole group can still be unfair to one kid; fair means everyone plays."},"relearn":"Fair friends leave no one out, even when it's the easy thing.","persona":"any","source":"fairness / belonging"},
  {"id":"ss-1201","cat":"fair-friends","type":"strike-rewrite","hook":"\"Only the strong kids get to choose the game.\"","myth":{"un":"Only strong kids choose the game.","re":"Everyone gets a say in what to play.","why":"Fair play means each kid's idea gets a turn, big or small."},"relearn":"Every single kid belongs and gets a fair say.","persona":"any","source":"fairness / voice"},
  {"id":"ss-1202","cat":"fair-friends","type":"strike-rewrite","hook":"\"He can't play with us, he's in a wheelchair.\"","myth":{"un":"Kids in wheelchairs can't play.","re":"Any kid can play; we just find a way to include them.","why":"Changing the game a little so everyone joins is the fair, kind thing."},"relearn":"Every single kid belongs; we make room for everyone.","persona":"any","source":"belonging / inclusion"},
  {"id":"ss-1203","cat":"fair-friends","type":"strike-rewrite","hook":"\"If you're not their friend, you can't join the game.\"","myth":{"un":"Only friends can join the game.","re":"Anyone can join, and that's how new friends start.","why":"Today's stranger becomes tomorrow's friend when you let them play."},"relearn":"Anyone can be friends with anyone; everyone may join.","persona":"any","source":"friendship / inclusion"},
  {"id":"ss-1204","cat":"fair-friends","type":"match","hook":"Match each fair move to the happy thing it brings.","pairs":[{"left":"Everyone gets a turn","right":"Nobody feels left out"},{"left":"Pick teams by skill, not gender","right":"The best, fairest match"},{"left":"Invite the new kid in","right":"A brand-new friend"},{"left":"Take turns being captain","right":"Everyone gets to lead"},{"left":"Share the only bat","right":"Two happy batters"}],"relearn":"Fair play makes everyone happier.","persona":"any","source":"fairness"},
  {"id":"ss-1205","cat":"fair-friends","type":"match","hook":"Match the kind thing a friend says to who feels welcome.","pairs":[{"left":"\"Come sit with us\"","right":"The kid eating alone"},{"left":"\"You can be on my team\"","right":"The kid picked last"},{"left":"\"Let's make space for you\"","right":"The kid in a wheelchair"},{"left":"\"You bat next\"","right":"The cricket-loving girl"},{"left":"\"Join our dance\"","right":"The dance-loving boy"}],"relearn":"Kind words turn a left-out kid into a welcome friend.","persona":"any","source":"inclusion / kindness"},
  {"id":"ss-1206","cat":"fair-friends","type":"match","hook":"Match each kid to a fair way to bring them into the game.","pairs":[{"left":"A shy new girl","right":"Ask her to be the catcher"},{"left":"A small younger boy","right":"Put him on your team"},{"left":"A Tamil-speaking kid","right":"Teach each other a word"},{"left":"A kid arriving late","right":"Save the next turn for them"},{"left":"A kid sitting all alone","right":"Wave them over to play"}],"relearn":"There's a fair, kind way to include every single kid.","persona":"any","source":"inclusion"},
  {"id":"ss-1207","cat":"fair-friends","type":"match","hook":"Match each fair playground rule to what it makes sure of.","pairs":[{"left":"Take turns","right":"Each kid gets a go"},{"left":"Be kind","right":"No one is teased"},{"left":"Everyone plays","right":"No one waits forever"},{"left":"Leave no one out","right":"Every kid belongs"},{"left":"Mix the teams","right":"Friends play with new kids"}],"relearn":"Fair rules make the playground welcome for all.","persona":"any","source":"fairness / rules"},
  {"id":"ss-1208","cat":"fair-friends","type":"match","hook":"Match the unfair move to the fairer one beside it.","pairs":[{"left":"\"No girls allowed\"","right":"\"Anyone can play\""},{"left":"\"You wait, you're new\"","right":"\"Come join right now\""},{"left":"\"Boys go first\"","right":"\"Let's take turns\""},{"left":"\"Only my gang plays\"","right":"\"There's room for all\""},{"left":"\"You're too slow\"","right":"\"You're on my team\""}],"relearn":"Every unfair rule has a fair, kind way to do it instead.","persona":"any","source":"fairness"},
  {"id":"ss-1209","cat":"fair-friends","type":"match","hook":"Match each kid's wish to the friend who helps it come true.","pairs":[{"left":"Wants to be picked","right":"A friend says \"you're with us\""},{"left":"Wants a turn on the swing","right":"A friend shares it"},{"left":"Wants to lead the game","right":"A friend takes turns leading"},{"left":"Wants to feel welcome","right":"A friend waves them over"},{"left":"Wants to be heard","right":"A friend listens to their idea"}],"relearn":"A fair friend helps every kid feel they belong.","persona":"any","source":"belonging / friendship"},
  {"id":"ss-1210","cat":"fair-friends","type":"match","hook":"Match each game to a fair way everyone gets to join.","pairs":[{"left":"Gully cricket","right":"Everyone gets to bat"},{"left":"Kho-kho","right":"Take turns being chaser"},{"left":"Skipping rope","right":"Line up for turns"},{"left":"Carrom","right":"Pick partners fairly"},{"left":"Hide-and-seek","right":"Everyone gets to seek"}],"relearn":"Every game has a fair way for everyone to play.","persona":"any","source":"fairness / play"},
  {"id":"ss-1211","cat":"fair-friends","type":"reflect","hook":"Lensy wonders: who in your class would you like to play with more?","prompt":"Picture that kid.","options":["The new kid","Someone who's shy","Someone who sits alone","A kid I don't know yet"],"affirm":"That's a kind idea. One \"come play\" can make a whole day brighter.","relearn":"You can choose to include someone new, any day.","persona":"any","source":"prosocial / empathy"},
  {"id":"ss-1212","cat":"fair-friends","type":"reflect","hook":"Lensy asks: what makes a friend feel fair to you?","prompt":"Think about it.","options":["They share","They take turns","They let me join","They listen to me"],"affirm":"Yes, that's what fair friends do, and you can do it too.","relearn":"Fair friends share, take turns, and include everyone.","persona":"Aria","source":"reflection / fairness"},
  {"id":"ss-1213","cat":"fair-friends","type":"reflect","hook":"Lensy wonders: how does it feel when someone says \"come play\"?","prompt":"Remember a time.","options":["Happy","Welcome","Excited","Like I belong"],"affirm":"That warm feeling is what you give when you invite someone in.","relearn":"A simple invite makes another kid feel they belong.","persona":"any","source":"empathy"},
  {"id":"ss-1214","cat":"fair-friends","type":"reflect","hook":"Lensy asks: what could you do if you saw a kid left out?","prompt":"Think of one thing.","options":["Wave them over","Ask them to join","Sit with them","Share my turn"],"affirm":"Any of those is a brave, fair thing to do. You'd be a kind friend.","relearn":"There are many kind ways to include a left-out kid.","persona":"any","source":"prosocial"},
  {"id":"ss-1215","cat":"fair-friends","type":"reflect","hook":"Lensy wonders: what's a game you'd love to teach a new friend?","prompt":"Pick your favourite.","options":["Cricket","Hide-and-seek","Kho-kho","Skipping"],"affirm":"Teaching a game is a lovely way to make a new friend feel welcome.","relearn":"Sharing what you love is a fair, friendly thing to do.","persona":"any","source":"reflection / friendship"},
  {"id":"ss-1216","cat":"fair-friends","type":"reflect","hook":"Lensy asks: when did a friend make YOU feel included?","prompt":"Remember that moment.","options":["They picked me","They saved my turn","They asked me to join","They sat with me"],"affirm":"That kindness stayed with you. You can pass it on to someone else.","relearn":"Remembering being included helps us include others.","persona":"any","source":"empathy"},
  {"id":"ss-1217","cat":"fair-friends","type":"reflect","hook":"Lensy wonders: what would make your playground fair for everyone?","prompt":"Imagine it.","options":["Everyone plays","We take turns","No one's left out","We're kind"],"affirm":"That's a playground where every kid belongs. You can help build it.","relearn":"A fair playground is one where every single kid belongs.","persona":"any","source":"reflection / fairness"},
  {"id":"ss-1218","cat":"fair-friends","type":"reflect","hook":"Lensy asks: who's someone different from you who'd be a fun friend?","prompt":"Think of them.","options":["A kid from another place","A kid who speaks another language","A new kid","Someone I just met"],"affirm":"Different friends bring new games and ideas. That's wonderful.","relearn":"A kid different from you can be a wonderful friend.","persona":"any","source":"empathy / difference"},
  {"id":"ss-1219","cat":"fair-friends","type":"build","hook":"Build the rules for a playground where everyone belongs.","prompt":"Pick the fair rules to add.","pieces":["everyone can play","take turns","be kind","leave no one out","mix the teams","boys go first"],"mode":"assemble","key":["everyone can play","take turns","be kind","leave no one out","mix the teams"],"relearn":"Fair rules: everyone plays, take turns, be kind, leave no one out.","persona":"any","source":"fairness / rules"},
  {"id":"ss-1220","cat":"fair-friends","type":"build","hook":"Build a kind way to bring a left-out kid into the game.","prompt":"Put the steps in order.","pieces":["notice the kid is alone","walk over and smile","say \"come play with us\"","find them a turn"],"mode":"sequence","key":["notice the kid is alone","walk over and smile","say \"come play with us\"","find them a turn"],"relearn":"Notice, go over, invite, and give them a turn.","persona":"any","source":"inclusion / prosocial"},
  {"id":"ss-1221","cat":"fair-friends","type":"build","hook":"Build a fair team for the relay race.","prompt":"Pick who gets on the team.","pieces":["a fast girl","a strong boy","the new kid","a kid who loves to run","only your best friends"],"mode":"assemble","key":["a fast girl","a strong boy","the new kid","a kid who loves to run"],"relearn":"Fair teams pick on skill and welcome everyone, not just your gang.","persona":"any","source":"fairness / teams"},
  {"id":"ss-1222","cat":"fair-friends","type":"build","hook":"Build the steps to fix it when a friend is left out.","prompt":"Put the kind steps in order.","pieces":["see that a friend is sad","ask what's wrong","help them get a turn","play together"],"mode":"sequence","key":["see that a friend is sad","ask what's wrong","help them get a turn","play together"],"relearn":"See, ask, help them in, and play together.","persona":"Aria","source":"prosocial / sequence"},
  {"id":"ss-1223","cat":"fair-friends","type":"build","hook":"Build a welcome for a new kid on their first day.","prompt":"Pick the welcoming things to do.","pieces":["say hello","tell them your name","ask them to play","show them the games","ignore them"],"mode":"assemble","key":["say hello","tell them your name","ask them to play","show them the games"],"relearn":"A warm welcome helps a new kid feel they belong.","persona":"any","source":"inclusion / belonging"},
  {"id":"ss-1224","cat":"fair-friends","type":"build","hook":"Build the fair way to share one swing among four kids.","prompt":"Put the steps in order.","pieces":["make a turn line","count to ten each","swap to the next kid","everyone gets a go"],"mode":"sequence","key":["make a turn line","count to ten each","swap to the next kid","everyone gets a go"],"relearn":"Taking fair turns means every kid gets a go.","persona":"any","source":"fairness / turn-taking"},
  {"id":"ss-1225","cat":"fair-friends","type":"build","hook":"Build a team of fair friends from these kids.","prompt":"Pick the kids who play fair.","pieces":["a kid who shares turns","a kid who invites others","a kid who's kind to all","a kid who leaves no one out","a kid who hogs the ball"],"mode":"assemble","key":["a kid who shares turns","a kid who invites others","a kid who's kind to all","a kid who leaves no one out"],"relearn":"Fair friends share, invite, and leave no one out.","persona":"any","source":"fairness / friendship"},
  {"id":"ss-1260","cat":"strong-gentle","type":"strike-rewrite","hook":"Dadi says \"a brave boy never cries.\"","myth":{"un":"A brave boy never cries.","re":"Brave kids cry too; tears let big feelings out.","why":"Crying is how everyone lets a big feeling go."},"relearn":"Crying is okay for boys and girls; it helps big feelings out.","persona":"Vihaan","source":"emotional health (links g01)"},
  {"id":"ss-1261","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Tears mean you're weak.\"","myth":{"un":"Tears mean you are weak.","re":"Tears just mean a feeling is big; that is not weak.","why":"Letting a feeling out takes its own kind of brave."},"relearn":"Crying is okay; it helps big feelings out, not a sign of weakness.","persona":"any","source":"emotional health"},
  {"id":"ss-1262","cat":"strong-gentle","type":"strike-rewrite","hook":"A cousin says \"gentle boys aren't real boys.\"","myth":{"un":"Gentle boys aren't real boys.","re":"Boys can be gentle and caring: that is real strength.","why":"Being kind and gentle is something to be proud of."},"relearn":"Boys can be warm, gentle and caring; that is wonderful.","persona":"Faizan-type","source":"both-directions"},
  {"id":"ss-1263","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Strong kids never feel scared.\"","myth":{"un":"Strong kids never feel scared.","re":"Strong kids feel scared too, and do the kind thing anyway.","why":"Feeling scared and still helping is what brave really is."},"relearn":"Every feeling is okay; being scared sometimes is part of being brave.","persona":"any","source":"emotional range"},
  {"id":"ss-1264","cat":"strong-gentle","type":"strike-rewrite","hook":"\"You have to be tough to be a leader.\"","myth":{"un":"You must be tough to be a leader.","re":"The best leaders are strong AND gentle: they listen too.","why":"Listening and caring help everyone follow happily."},"relearn":"Real strength is kind; gentle leaders are strong leaders.","persona":"Aria","source":"emotional range"},
  {"id":"ss-1265","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Hugging your friend goodbye is just for girls.\"","myth":{"un":"Hugging a friend goodbye is just for girls.","re":"Any kid can hug a friend goodbye: warmth is for everyone.","why":"Showing you care with a hug is kind, for any kid."},"relearn":"Boys can be warm and affectionate too: that's not 'not for boys'.","persona":"Faizan-type","source":"both-directions"},
  {"id":"ss-1266","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Girls are too soft to be strong.\"","myth":{"un":"Girls are too soft to be strong.","re":"Girls can be gentle and strong at the same time.","why":"Gentle and strong are not opposites; they live together."},"relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"emotional range"},
  {"id":"ss-1267","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Don't be a baby\" when a friend cries.","myth":{"un":"A crying friend is being 'a baby'.","re":"A crying friend just has a big feeling; comfort them.","why":"Kindness when someone cries is real strength."},"relearn":"Helping a friend let tears out is real strength, not weakness.","persona":"any","source":"empathy"},
  {"id":"ss-1268","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Boys should hide it when they feel sad.\"","myth":{"un":"Boys should hide when they feel sad.","re":"Boys get to feel sad and say it out loud, like anyone.","why":"Naming a feeling out loud helps it feel smaller."},"relearn":"Boys get to feel everything, not just 'tough'.","persona":"Vihaan","source":"emotional health"},
  {"id":"ss-1269","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Real heroes are only big and tough.\"","myth":{"un":"Real heroes are only big and tough.","re":"The best heroes are strong AND gentle: kind and brave.","why":"A kind hero helps people, not just lifts heavy things."},"relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-1270","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Being gentle means you can't stand up for yourself.\"","myth":{"un":"Being gentle means you can't stand up for yourself.","re":"Gentle kids can speak up firmly and kindly too.","why":"You can say 'that's not fair' in a calm, gentle voice."},"relearn":"You can be gentle and strong; they're not opposites.","persona":"Aria","source":"emotional range"},
  {"id":"ss-1271","cat":"strong-gentle","type":"strike-rewrite","hook":"\"Boys have to win or hide their tears.\"","myth":{"un":"Boys must win or hide their tears.","re":"Boys can lose a game, cry, and still be okay.","why":"Letting the feeling out helps, then the play goes on."},"relearn":"Crying is okay for boys; it helps big feelings out.","persona":"Faizan-type","source":"emotional health"},
  {"id":"ss-1272","cat":"strong-gentle","type":"sort","hook":"Sort: a feeling a boy is allowed, or a silly old rule?","items":[{"id":"a","text":"A boy may feel sad and cry"},{"id":"b","text":"Boys must never feel scared"},{"id":"c","text":"A boy may feel gentle and soft"},{"id":"d","text":"Big boys can't cry"},{"id":"e","text":"A boy may feel proud and happy"},{"id":"f","text":"Boys can only feel tough"}],"bins":[{"id":"yes","label":"Yes, he can","valence":"pos"},{"id":"rule","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"rule","c":"yes","d":"rule","e":"yes","f":"rule"},"relearn":"Boys get to feel everything, not just 'tough'.","persona":"Vihaan","source":"emotional health"},
  {"id":"ss-1273","cat":"strong-gentle","type":"sort","hook":"Sort each one: strong, or gentle? (Anyone can do both!)","items":[{"id":"a","text":"Lifting a heavy water pot"},{"id":"b","text":"Wiping a friend's tears"},{"id":"c","text":"Winning a tug-of-war"},{"id":"d","text":"Singing a baby to sleep"},{"id":"e","text":"Pushing a stuck cart"},{"id":"f","text":"Holding a tiny chick softly"}],"bins":[{"id":"strong","label":"Strong","valence":"pos"},{"id":"gentle","label":"Gentle","valence":"pos"}],"key":{"a":"strong","b":"gentle","c":"strong","d":"gentle","e":"strong","f":"gentle"},"relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"emotional range"},
  {"id":"ss-1274","cat":"strong-gentle","type":"sort","hook":"A friend is crying. Sort: a kind thing, or an unkind thing?","items":[{"id":"a","text":"Sitting beside them quietly"},{"id":"b","text":"Laughing at their tears"},{"id":"c","text":"Saying 'it's okay to cry'"},{"id":"d","text":"Telling them to stop being a baby"},{"id":"e","text":"Bringing them their water bottle"},{"id":"f","text":"Walking off and ignoring them"}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Kindness when someone cries is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1275","cat":"strong-gentle","type":"sort","hook":"Sort: real strength, or just being rough?","items":[{"id":"a","text":"Helping a small kid carry a bag"},{"id":"b","text":"Shoving to get to the front"},{"id":"c","text":"Gently helping a fallen friend up"},{"id":"d","text":"Grabbing a toy by force"},{"id":"e","text":"Sharing your snack with a sad friend"},{"id":"f","text":"Squeezing someone's arm too hard"}],"bins":[{"id":"strong","label":"Real strength","valence":"pos"},{"id":"rough","label":"Just rough","valence":"neg"}],"key":{"a":"strong","b":"rough","c":"strong","d":"rough","e":"strong","f":"rough"},"relearn":"Real strength is kind; pushing and grabbing are just unkind.","persona":"any","source":"values"},
  {"id":"ss-1276","cat":"strong-gentle","type":"sort","hook":"Big feelings! Sort each one: okay to feel, or a silly old rule?","items":[{"id":"a","text":"It's okay to feel angry sometimes"},{"id":"b","text":"Only girls are allowed to feel sad"},{"id":"c","text":"It's okay to feel scared sometimes"},{"id":"d","text":"Only boys are allowed to feel brave"},{"id":"e","text":"It's okay to feel really happy"},{"id":"f","text":"Some kids aren't allowed to feel"}],"bins":[{"id":"okay","label":"Okay to feel","valence":"pos"},{"id":"rule","label":"Silly old rule","valence":"neg"}],"key":{"a":"okay","b":"rule","c":"okay","d":"rule","e":"okay","f":"rule"},"relearn":"Every feeling is okay for every kid.","persona":"any","source":"emotions"},
  {"id":"ss-1277","cat":"strong-gentle","type":"sort","hook":"What makes a strong-and-gentle hero? Sort: yes, or no.","items":[{"id":"a","text":"Helps a hurt friend up"},{"id":"b","text":"Teases crying kids"},{"id":"c","text":"Is brave AND kind"},{"id":"d","text":"Has to win every single time"},{"id":"e","text":"Listens when a friend is sad"},{"id":"f","text":"Never lets anyone feel anything"}],"bins":[{"id":"yes","label":"Yes, a hero","valence":"pos"},{"id":"no","label":"Not really","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-1278","cat":"strong-gentle","type":"sort","hook":"Sort each kid: showing strong, or showing gentle? Both are great.","items":[{"id":"a","text":"Aria carrying her baby brother"},{"id":"b","text":"Kabir tucking in his teddy"},{"id":"c","text":"Vihaan pulling a loaded wagon"},{"id":"d","text":"Megha's son patting the cat"},{"id":"e","text":"A girl climbing high on the bars"},{"id":"f","text":"A boy bandaging a doll's knee"}],"bins":[{"id":"strong","label":"Strong","valence":"pos"},{"id":"gentle","label":"Gentle","valence":"pos"}],"key":{"a":"gentle","b":"gentle","c":"strong","d":"gentle","e":"strong","f":"gentle"},"relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"both-directions"},
  {"id":"ss-1279","cat":"strong-gentle","type":"sort","hook":"Sort: a kind way to be brave, or just showing off?","items":[{"id":"a","text":"Standing up for a teased friend"},{"id":"b","text":"Bragging 'I'm the toughest'"},{"id":"c","text":"Trying a scary slide to help a pal"},{"id":"d","text":"Daring others to get hurt"},{"id":"e","text":"Telling a sad friend 'I'm here'"},{"id":"f","text":"Pushing in to look the strongest"}],"bins":[{"id":"brave","label":"Kind & brave","valence":"pos"},{"id":"show","label":"Just showing off","valence":"neg"}],"key":{"a":"brave","b":"show","c":"brave","d":"show","e":"brave","f":"show"},"relearn":"Real strength is kind; showing off and daring hurt is unkind.","persona":"any","source":"values"},
  {"id":"ss-1280","cat":"strong-gentle","type":"role-play","hook":"A boy at the park is wiping his eyes, trying not to cry.","setup":"Sit by him and say, in a kind voice:","yourLine":[{"text":"\"It's okay to cry. I'll sit with you.\"","best":true},{"text":"\"Stop it, big boys don't cry.\""}],"relearn":"Helping a friend let tears out is real strength.","persona":"Kabir","source":"voice / empathy"},
  {"id":"ss-1281","cat":"strong-gentle","type":"role-play","hook":"Your team lost the race and you feel like crying.","setup":"Say how you feel, out loud:","yourLine":[{"text":"\"I feel sad we lost, and that's okay.\"","best":true},{"text":"\"I have to hide it so no one sees.\""}],"relearn":"Naming a feeling out loud helps it feel smaller.","persona":"Vihaan","source":"affect labelling / voice"},
  {"id":"ss-1282","cat":"strong-gentle","type":"role-play","hook":"A friend says you're 'too gentle' to be on the strong team.","setup":"Stand tall and say, calmly:","yourLine":[{"text":"\"I'm gentle AND strong. I can do both.\"","best":true},{"text":"\"Okay, maybe I can't be strong.\""}],"relearn":"You can be gentle and strong; they're not opposites.","persona":"Aria","source":"voice / self-concept"},
  {"id":"ss-1283","cat":"strong-gentle","type":"role-play","hook":"Your little cousin scraped a knee and is sobbing.","setup":"Comfort them. Say, softly:","yourLine":[{"text":"\"Let the tears out. I'm right here with you.\"","best":true},{"text":"\"Don't be a baby, it's nothing.\""}],"relearn":"Kindness when someone cries is real strength.","persona":"Faizan-type","source":"voice / empathy"},
  {"id":"ss-1284","cat":"strong-gentle","type":"role-play","hook":"A friend laughs that you hugged your dad goodbye at the gate.","setup":"Say it proudly:","yourLine":[{"text":"\"I love hugging my dad. Hugs are for everyone.\"","best":true},{"text":"\"Okay, I won't hug him anymore.\""}],"relearn":"Boys can be warm and affectionate too.","persona":"Faizan-type","source":"voice / both-directions"},
  {"id":"ss-1285","cat":"strong-gentle","type":"role-play","hook":"You feel a big angry feeling rising up inside.","setup":"Name it out loud instead of pushing it down:","yourLine":[{"text":"\"I feel angry right now, and that's okay.\"","best":true},{"text":"\"I should pretend I'm fine.\""}],"relearn":"Naming a feeling out loud helps it feel smaller.","persona":"Aria","source":"affect labelling / voice"},
  {"id":"ss-1286","cat":"strong-gentle","type":"role-play","hook":"A classmate is being teased for crying when he missed his mummy.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"Missing your mummy is okay. Don't tease him.\"","best":true},{"text":"\"Yeah, what a baby.\""}],"relearn":"Helping a friend let tears out is real strength, not weakness.","persona":"any","source":"voice / empathy"},
  {"id":"ss-1287","cat":"strong-gentle","type":"role-play","hook":"You want to be gentle with the new puppy, but a friend says 'grab it!'","setup":"Show the kind, strong way. Say:","yourLine":[{"text":"\"We hold puppies softly, like this.\"","best":true},{"text":"\"Okay, let's grab it hard.\""}],"relearn":"Real strength is kind; being gentle is something to be proud of.","persona":"Kabir","source":"voice / values"},
  {"id":"ss-1288","cat":"strong-gentle","type":"branch","hook":"Your friend trips and cries. Some kids start to laugh.","options":[{"text":"Help him up; say 'it's okay to cry'","consequence":"He calms; he feels safe.","outcome":"kind","best":true},{"text":"Laugh along with them","consequence":"He feels worse, alone."},{"text":"Walk away","consequence":"He cries by himself."}],"debrief":"Comforting a crying friend is the strong, kind choice.","relearn":"Kindness when someone cries is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1289","cat":"strong-gentle","type":"branch","hook":"You feel scared on the tall slide; your eyes go teary.","options":[{"text":"Say 'I feel scared' and ask for a hand","consequence":"A grown-up helps; you feel braver.","outcome":"brave","best":true},{"text":"Push it down and freeze","consequence":"The scared feeling stays stuck."},{"text":"Tease a kid to look tough","consequence":"They feel bad; you still feel scared."}],"debrief":"Saying you're scared is brave; feelings shrink when named.","relearn":"Naming a feeling out loud helps it feel smaller.","persona":"Vihaan","source":"affect labelling"},
  {"id":"ss-1290","cat":"strong-gentle","type":"branch","hook":"A boy in your group gently rocks the class doll to sleep.","options":[{"text":"Join in; rock the other doll softly","consequence":"You both practise care; it's warm.","outcome":"warm","best":true},{"text":"Tell him dolls aren't for boys","consequence":"He stops; that's a shame."},{"text":"Grab the doll to be rough","consequence":"The gentle play is spoiled."}],"debrief":"Boys caring gently is wonderful; care is for every kid.","relearn":"A boy playing gently is practising care, and that is wonderful.","persona":"Faizan-type","source":"both-directions"},
  {"id":"ss-1291","cat":"strong-gentle","type":"branch","hook":"Your sister is angry and stomping. A grown-up says 'good girls aren't angry'.","options":[{"text":"Sit with her; say 'angry is okay'","consequence":"She feels heard and calms.","outcome":"kind","best":true},{"text":"Tell her to be quiet and smile","consequence":"She hides it; it stays bottled."},{"text":"Shout angrily back","consequence":"Now you're both upset."}],"debrief":"Anger is okay for every kid; 'good girls' get to feel it too.","relearn":"Every feeling is okay for every kid, including anger.","persona":"Aria","source":"emotions"},
  {"id":"ss-1292","cat":"strong-gentle","type":"branch","hook":"A friend is sad about losing his pet. You want to help.","options":[{"text":"Sit close and listen to him","consequence":"He feels less alone; sharing helps.","outcome":"kind","best":true},{"text":"Say 'be tough, forget it'","consequence":"He feels his sadness doesn't matter."},{"text":"Change the subject to your toy","consequence":"He stays sad and ignored."}],"debrief":"Listening to a sad friend is a gentle, strong thing to do.","relearn":"Being there when a friend is sad is real strength.","persona":"Kabir","source":"empathy"},
  {"id":"ss-1293","cat":"strong-gentle","type":"branch","hook":"You're the strongest at tug-of-war. A smaller kid wants to try.","options":[{"text":"Cheer them on; play gently","consequence":"Everyone has fun; you're strong AND kind.","outcome":"kind","best":true},{"text":"Pull as hard as you can","consequence":"They tumble and feel left out."},{"text":"Say they're too weak","consequence":"They walk off feeling small."}],"debrief":"Using strength kindly so everyone can join is real strength.","relearn":"Real strength is kind; everyone gets to play.","persona":"any","source":"values"},
  {"id":"ss-1294","cat":"strong-gentle","type":"branch","hook":"Your friend Razia is crying quietly; others haven't noticed.","options":[{"text":"Go to her; ask if she's okay","consequence":"She lets tears out; she feels cared for.","outcome":"kind","best":true},{"text":"Pretend you didn't see","consequence":"She keeps it inside, alone."},{"text":"Say crying is for babies","consequence":"She feels ashamed of her feeling."}],"debrief":"Noticing and comforting a crier is gentle and strong.","relearn":"Helping a friend let tears out is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1295","cat":"strong-gentle","type":"branch","hook":"A bigger kid squeezes a friend's arm, calling it 'being strong'.","options":[{"text":"Say 'that hurts. Strong means kind'","consequence":"He lets go; your friend is okay.","outcome":"brave","best":true},{"text":"Join in to look strong","consequence":"Your friend gets hurt."},{"text":"Laugh, it's just a game","consequence":"The hurting carries on; not fair."}],"debrief":"Speaking up that strong should be kind is brave and fair.","relearn":"Real strength is kind; hurting is just unkind.","persona":"any","source":"values"},
  {"id":"ss-1296","cat":"strong-gentle","type":"reflect","hook":"Lensy wonders about a time you were gentle with someone little.","prompt":"How did being gentle feel?","options":["Warm","Calm","Proud","Happy"],"affirm":"That gentleness is a strength you carry. It's lovely.","relearn":"Gentleness is something to be proud of.","persona":"any","source":"self-esteem"},
  {"id":"ss-1297","cat":"strong-gentle","type":"reflect","hook":"Everyone has big feelings. Lensy asks about yours.","prompt":"Which big feeling do you have sometimes?","options":["Sad","Angry","Scared","Super happy"],"affirm":"Every one of those is okay to feel. You're allowed all of them.","relearn":"Every feeling is okay for every kid.","persona":"any","source":"emotions"},
  {"id":"ss-1298","cat":"strong-gentle","type":"reflect","hook":"You can be strong AND gentle. Lensy is curious.","prompt":"When do you feel strong?","options":["Helping carry things","Climbing high","Standing up kindly","Cheering a friend"],"affirm":"That's your strength, and you can be gentle with it too.","relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"self-concept"},
  {"id":"ss-1299","cat":"strong-gentle","type":"reflect","hook":"Crying lets big feelings out. Lensy wonders gently.","prompt":"What helps you feel better after you cry?","options":["A hug","Quiet time","Talking to someone","A drink of water"],"affirm":"That's a kind way to care for yourself. Crying is okay.","relearn":"Crying is okay; it helps big feelings out.","persona":"Kabir","source":"self-regulation"},
  {"id":"ss-1300","cat":"strong-gentle","type":"reflect","hook":"Comforting a friend is a kind kind of strong.","prompt":"How do you comfort a friend who's sad?","options":["Sit with them","Give a hug","Say 'I'm here'","Share my snack"],"affirm":"All of those are caring and strong. What a good friend.","relearn":"Kindness when someone is sad is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1301","cat":"strong-gentle","type":"reflect","hook":"Boys feel everything too. Lensy asks a boy or anyone.","prompt":"What's a feeling you had today?","options":["Excited","A bit sad","Cosy","Frustrated"],"affirm":"Whatever you felt, it's okay. Every feeling is for every kid.","relearn":"Boys get to feel everything, not just 'tough'.","persona":"Faizan-type","source":"emotions"},
  {"id":"ss-1302","cat":"strong-gentle","type":"reflect","hook":"Heroes are strong AND gentle. Lensy wonders about yours.","prompt":"What makes someone a hero to you?","options":["They're kind","They're brave","They help others","They listen"],"affirm":"You see it: real heroes are strong AND gentle, like you.","relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-1303","cat":"strong-gentle","type":"reflect","hook":"Being gentle takes its own kind of brave. Lensy is curious.","prompt":"Who do you like to be gentle with?","options":["A baby","A pet","A friend","A little plant"],"affirm":"Caring gently for them is wonderful. Be proud of it.","relearn":"Gentleness is something to be proud of.","persona":"any","source":"self-esteem"},
  {"id":"ss-1304","cat":"strong-gentle","type":"match","hook":"Match each kid to the strong-and-gentle thing they're doing.","pairs":[{"left":"Vihaan, carrying the big drum","right":"Being strong"},{"left":"Kabir, rocking his baby sister","right":"Being gentle"},{"left":"Aria, leading the morning song","right":"Being a brave leader"},{"left":"A boy, drying his friend's tears","right":"Being kind and caring"},{"left":"A girl, helping a pal up the wall","right":"Being strong and helpful"}],"relearn":"Every kid can be both strong AND gentle.","persona":"any","source":"both-directions"},
  {"id":"ss-1305","cat":"strong-gentle","type":"match","hook":"Match the feeling to a kind thing you can do with it.","pairs":[{"left":"I feel sad","right":"Ask for a hug"},{"left":"I feel angry","right":"Take some deep breaths"},{"left":"I feel scared","right":"Hold a grown-up's hand"},{"left":"I feel like crying","right":"Let the tears out"},{"left":"I feel happy","right":"Share it with a friend"}],"relearn":"Every feeling is okay; there's a kind way to handle each one.","persona":"any","source":"self-regulation"},
  {"id":"ss-1306","cat":"strong-gentle","type":"match","hook":"Match the words to what they are.","pairs":[{"left":"\"It's okay to cry, I'm here.\"","right":"A kind voice"},{"left":"\"Don't be such a baby!\"","right":"An unkind voice"},{"left":"\"You can be strong and gentle.\"","right":"A true, helpful thing"},{"left":"\"Big boys never cry.\"","right":"A silly old rule"},{"left":"\"I'll sit with you a while.\"","right":"A caring offer"}],"relearn":"Kind words help a crier; 'don't be a baby' is unkind.","persona":"any","source":"empathy"},
  {"id":"ss-1307","cat":"strong-gentle","type":"match","hook":"Match the kid to a moment, and every feeling is for everyone.","pairs":[{"left":"A gentle boy with a kitten","right":"Soft and caring"},{"left":"A powerful girl on the bars","right":"Strong and bold"},{"left":"A tearful boy missing home","right":"Sad and okay"},{"left":"A fierce girl leading the team","right":"Brave and loud"},{"left":"A tender boy hugging his dad","right":"Warm and loving"}],"relearn":"Every feeling is okay for every kid; boys and girls feel it all.","persona":"any","source":"emotions"},
  {"id":"ss-1308","cat":"strong-gentle","type":"match","hook":"Match each action to what it really is.","pairs":[{"left":"Helping a fallen friend up","right":"Kind and strong"},{"left":"Shoving to the front of the line","right":"Just rough and unfair"},{"left":"Carrying a bag for a tired kid","right":"Strong and helpful"},{"left":"Grabbing toys by force","right":"Unkind and grabby"},{"left":"Speaking up gently for someone","right":"Brave and kind"}],"relearn":"Real strength is kind; pushing and grabbing are just unkind.","persona":"any","source":"values"},
  {"id":"ss-1309","cat":"strong-gentle","type":"match","hook":"Match the strong-and-gentle hero to their kind power.","pairs":[{"left":"Lifts the heavy gate","right":"Strong arms"},{"left":"Listens to a sad friend","right":"Listening heart"},{"left":"Holds a baby bird safely","right":"Gentle hands"},{"left":"Tries the scary jump for a pal","right":"Brave heart"},{"left":"Says 'come play with us'","right":"Kind words"}],"relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-1310","cat":"strong-gentle","type":"match","hook":"Match each crying friend to the kindest thing to say.","pairs":[{"left":"Friend missed the bus and cries","right":"\"Let's wait together.\""},{"left":"Friend dropped his ice cream","right":"\"Oh no, that's so sad.\""},{"left":"Friend is scared of the dog","right":"\"I'll stand with you.\""},{"left":"Friend lost the game and sulks","right":"\"It's okay, that's hard.\""},{"left":"Friend misses her mummy","right":"\"I'm here till she comes.\""}],"relearn":"Kind words help a crying friend feel less alone.","persona":"any","source":"care"},
  {"id":"ss-1311","cat":"strong-gentle","type":"build","hook":"Build a hero who is BOTH strong and gentle. Pick their powers.","prompt":"Tap the powers for your strong-and-gentle hero.","pieces":["strong arms","gentle hands","brave heart","kind words","good listening","big smile"],"mode":"assemble","key":["strong arms","gentle hands","brave heart","kind words","good listening","big smile"],"relearn":"The best heroes are strong AND gentle, like you can be.","persona":"any","source":"self-concept"},
  {"id":"ss-1312","cat":"strong-gentle","type":"build","hook":"Build a comfort kit to help a friend who's crying.","prompt":"Tap the kind things to put in the kit.","pieces":["a soft tissue","a warm hug","the words 'it's okay'","a cup of water","sitting close","time to feel"],"mode":"assemble","key":["a soft tissue","a warm hug","the words 'it's okay'","a cup of water","sitting close","time to feel"],"relearn":"Helping a friend let tears out is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1313","cat":"strong-gentle","type":"build","hook":"Build the steps to calm a big feeling, in order.","prompt":"Put the calm-down steps in order.","pieces":["Notice the big feeling","Name it: 'I feel ___'","Take three slow breaths","Ask for a hug or help"],"mode":"sequence","key":["Notice the big feeling","Name it: 'I feel ___'","Take three slow breaths","Ask for a hug or help"],"relearn":"Naming a feeling out loud helps it feel smaller.","persona":"Kabir","source":"self-regulation"},
  {"id":"ss-1314","cat":"strong-gentle","type":"build","hook":"Build the order to comfort a friend who just fell and cried.","prompt":"Put the kind steps in order.","pieces":["Go over to your friend","Ask 'are you okay?'","Help them sit up gently","Say 'it's okay to cry'"],"mode":"sequence","key":["Go over to your friend","Ask 'are you okay?'","Help them sit up gently","Say 'it's okay to cry'"],"relearn":"Kindness when someone cries is real strength.","persona":"any","source":"empathy"},
  {"id":"ss-1315","cat":"strong-gentle","type":"build","hook":"Build a 'feelings are for everyone' poster. Pick what belongs.","prompt":"Tap the true things for the poster.","pieces":["Boys can cry","Girls can be strong","Every feeling is okay","Strong and gentle together","Crying lets feelings out","Be kind to a crier"],"mode":"assemble","key":["Boys can cry","Girls can be strong","Every feeling is okay","Strong and gentle together","Crying lets feelings out","Be kind to a crier"],"relearn":"Every feeling is okay for every kid; strong and gentle go together.","persona":"any","source":"emotional range"},
  {"id":"ss-1316","cat":"strong-gentle","type":"build","hook":"Build a 'real strength' superhero who helps, not hurts.","prompt":"Tap the things that make strength kind.","pieces":["helps friends up","shares the load","plays gently","listens to feelings","cheers others on","never teases a crier"],"mode":"assemble","key":["helps friends up","shares the load","plays gently","listens to feelings","cheers others on","never teases a crier"],"relearn":"Real strength is kind; pushing and teasing are just unkind.","persona":"any","source":"values"},
  {"id":"ss-1317","cat":"strong-gentle","type":"build","hook":"Build the steps to be brave when you feel scared.","prompt":"Put the brave steps in order.","pieces":["Notice 'I feel scared'","Say it out loud","Hold a hand or a teddy","Try one small brave step"],"mode":"sequence","key":["Notice 'I feel scared'","Say it out loud","Hold a hand or a teddy","Try one small brave step"],"relearn":"Every feeling is okay; saying you're scared is part of being brave.","persona":"Vihaan","source":"affect labelling"},
  {"id":"ss-1350","cat":"toys-for-all","type":"sort","hook":"Lensy peeks in the toy basket. Who can play?","items":[{"id":"a","text":"A boy may play with the toy kitchen"},{"id":"b","text":"Only girls may hold the doll"},{"id":"c","text":"A girl may zoom the race car"},{"id":"d","text":"Boys can't have the tea set"},{"id":"e","text":"Anyone may build the train track"},{"id":"f","text":"Skipping rope is just for girls"}],"bins":[{"id":"yes","label":"Yes, anyone can","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"yes","b":"silly","c":"yes","d":"silly","e":"yes","f":"silly"},"relearn":"No toy is off-limits to a kid for being a girl or a boy.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-1351","cat":"toys-for-all","type":"sort","hook":"Things kids say at playtime. Kind, or unkind?","items":[{"id":"a","text":"\"Want a turn with my truck?\""},{"id":"b","text":"\"Boys can't play house!\""},{"id":"c","text":"\"Let's cook in the play-kitchen\""},{"id":"d","text":"\"Put that doll down, not for you\""},{"id":"e","text":"\"Be the doctor with my kit\""},{"id":"f","text":"\"Girls can't have the blocks\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Sharing and inviting is kind; saying a toy isn't for a kid is unkind.","persona":"any","source":"peer norms"},
  {"id":"ss-1352","cat":"toys-for-all","type":"sort","hook":"Help Lensy tidy the shelf. True, or a silly old rule?","items":[{"id":"a","text":"Anyone can love soft teddies"},{"id":"b","text":"Cars are only for boys"},{"id":"c","text":"Any kid can spin the top"},{"id":"d","text":"Dolls are only for girls"},{"id":"e","text":"Both girls and boys can do puzzles"},{"id":"f","text":"Toy tools are not for girls"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"\"This toy is only for boys/girls\" is a silly old rule; toys are for everyone.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-1353","cat":"toys-for-all","type":"sort","hook":"At the anganwadi, who gets the toy? Sort it.","items":[{"id":"a","text":"Whoever asked first, then we swap"},{"id":"b","text":"The boy, because he's a boy"},{"id":"c","text":"We set a timer and take turns"},{"id":"d","text":"The girl never gets the cricket bat"},{"id":"e","text":"We share, one builds while one watches"},{"id":"f","text":"Grab it and run away with it"}],"bins":[{"id":"fair","label":"Fair turn","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Everyone gets a turn; a toy isn't given or kept because of girl or boy.","persona":"Aria","source":"fairness"},
  {"id":"ss-1354","cat":"toys-for-all","type":"sort","hook":"Lensy made some toy signs. Welcoming, or leaving kids out?","items":[{"id":"a","text":"\"Everyone may play here\""},{"id":"b","text":"\"No girls\""},{"id":"c","text":"\"Take turns, all are welcome\""},{"id":"d","text":"\"Boys keep out\""},{"id":"e","text":"\"Come share with us\""},{"id":"f","text":"\"This corner is not for you\""}],"bins":[{"id":"welcome","label":"Welcoming","valence":"pos"},{"id":"out","label":"Leaves kids out","valence":"neg"}],"key":{"a":"welcome","b":"out","c":"welcome","d":"out","e":"welcome","f":"out"},"relearn":"A good play corner welcomes every kid; no one is shut out for being a girl or boy.","persona":"any","source":"inclusion"},
  {"id":"ss-1355","cat":"toys-for-all","type":"sort","hook":"Diya brought toys to share. What's a true thing about them?","items":[{"id":"a","text":"Any kid can push the toy bus"},{"id":"b","text":"A doll belongs only to girls"},{"id":"c","text":"A boy can rock the baby doll to sleep"},{"id":"d","text":"Blocks are too hard for girls"},{"id":"e","text":"Everyone can stack the rings"},{"id":"f","text":"The kitchen set is not for boys"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"silly","label":"Silly old rule","valence":"neg"}],"key":{"a":"true","b":"silly","c":"true","d":"silly","e":"true","f":"silly"},"relearn":"A boy caring for a doll is wonderful; no toy is fenced off by gender.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1356","cat":"toys-for-all","type":"sort","hook":"Lensy heard these on the playground. Fair, or not fair?","items":[{"id":"a","text":"\"You can borrow my doll next\""},{"id":"b","text":"\"This bat is mine forever, no turns\""},{"id":"c","text":"\"Let's both have a go on the slide\""},{"id":"d","text":"\"Girls can't join our train game\""},{"id":"e","text":"\"After me, it's your turn\""},{"id":"f","text":"\"Boys can't play with the dollhouse\""}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Taking turns and inviting everyone is fair; hogging or shutting kids out is not.","persona":"any","source":"fairness"},
  {"id":"ss-1357","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Blocks are boys' toys,\" says a cousin.","myth":{"un":"Blocks are only for boys.","re":"Any kid can build with blocks.","why":"Building helps every child's hands and ideas grow."},"relearn":"Blocks are for any kid that loves to build.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-1358","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Cooking sets are girls' toys.\"","myth":{"un":"Play-kitchens are only for girls.","re":"Any kid can cook in a play-kitchen.","why":"Pretend cooking is a skill everyone enjoys learning."},"relearn":"A boy at the play-kitchen is just having fun, like any kid.","persona":"Faizan-type","source":"occupations & care"},
  {"id":"ss-1359","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Baby dolls aren't for boys.\"","myth":{"un":"Baby dolls aren't for boys.","re":"Boys can care for a doll too.","why":"Pretend caring helps every child practise being gentle."},"relearn":"A boy holding a doll is practising care, and that's wonderful.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1360","cat":"toys-for-all","type":"strike-rewrite","hook":"\"That's a girls' colour cricket bat, not for you.\"","myth":{"un":"A pink cricket bat is only for girls.","re":"Any kid can swing any bat they like.","why":"A bat hits the ball just the same in every colour."},"relearn":"The toy is for playing, not for one kind of kid.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-1361","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Soft teddies make boys babyish.\"","myth":{"un":"Boys shouldn't cuddle soft toys.","re":"Any kid can love a cuddly teddy.","why":"A soft friend is cosy and comforting for everyone."},"relearn":"Loving a teddy is for any kid, big or small, girl or boy.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1362","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Toy tools belong to boys.\"","myth":{"un":"Toy hammers and tools are only for boys.","re":"Any kid can fix and build with toy tools.","why":"Tinkering and mending are great for every pair of hands."},"relearn":"A girl with a toy toolkit is just playing, the same as any kid.","persona":"any","source":"gender & play"},
  {"id":"ss-1363","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Skipping ropes are for girls only.\"","myth":{"un":"Skipping ropes are only for girls.","re":"Any kid can skip and jump.","why":"Skipping makes everyone giggly and out of breath the same way."},"relearn":"A boy that loves to skip is just having a good time.","persona":"any","source":"gender & play"},
  {"id":"ss-1364","cat":"toys-for-all","type":"strike-rewrite","hook":"\"You're too big to play with toys.\"","myth":{"un":"Some kids are 'too big' for the toys they love.","re":"You can play with what you love at any size.","why":"Fun has no size, and play is good for everyone."},"relearn":"No one can tell you a toy isn't for you.","persona":"Vihaan","source":"autonomy"},
  {"id":"ss-1365","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Dollhouses are silly for boys.\"","myth":{"un":"Dollhouses are silly for boys.","re":"Any kid can play house and tell little stories.","why":"Pretend homes help everyone imagine and care."},"relearn":"Playing house is wonderful for any kid that enjoys it.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1366","cat":"toys-for-all","type":"strike-rewrite","hook":"\"He can't share his truck with a girl.\"","myth":{"un":"Boys shouldn't share toys with girls.","re":"Anyone can share a toy with anyone.","why":"Sharing makes two friends instead of one lonely toy."},"relearn":"Toys are to share, and sharing makes friends.","persona":"any","source":"inclusion"},
  {"id":"ss-1367","cat":"toys-for-all","type":"strike-rewrite","hook":"\"Cars zoom, dolls are boring,\" a kid teases.","myth":{"un":"Some toys are 'better' than others.","re":"Every toy is fun for whoever loves it.","why":"What's fun for you is exactly the right toy for you."},"relearn":"There are no wrong toys; there's just what you enjoy.","persona":"any","source":"autonomy"},
  {"id":"ss-1368","cat":"toys-for-all","type":"role-play","hook":"A boy looks shyly at the play-kitchen, unsure.","setup":"Wave him over. Say it loud:","yourLine":[{"text":"\"Come cook with me, anyone can!\"","best":true},{"text":"\"That's only for girls, go away.\""}],"relearn":"Inviting a friend to any toy is how kind kids play.","persona":"Kabir","source":"voice / audio-first"},
  {"id":"ss-1369","cat":"toys-for-all","type":"role-play","hook":"Your friend says dolls aren't for you.","setup":"Say your brave, kind line aloud:","yourLine":[{"text":"\"Dolls are for everyone, I can play too!\"","best":true},{"text":"\"Okay, I'll just watch then.\""}],"relearn":"No one can tell you a toy isn't for you; say it out loud.","persona":"Faizan-type","source":"voice / audio-first"},
  {"id":"ss-1370","cat":"toys-for-all","type":"role-play","hook":"A girl wants a turn with the cricket bat.","setup":"Pass it over. Say:","yourLine":[{"text":"\"Here, your turn, then mine!\"","best":true},{"text":"\"No, girls don't get the bat.\""}],"relearn":"Taking turns with anyone is fair and friendly.","persona":"Aria","source":"voice / audio-first"},
  {"id":"ss-1371","cat":"toys-for-all","type":"role-play","hook":"Two kids both want the last toy car.","setup":"Make a kind plan. Say it loud:","yourLine":[{"text":"\"You go first, I'll count to ten!\"","best":true},{"text":"\"It's mine, I had it last time.\""}],"relearn":"A turn-taking plan keeps the fun fair for everyone.","persona":"Kabir","source":"voice / audio-first"},
  {"id":"ss-1372","cat":"toys-for-all","type":"role-play","hook":"A quiet kid stands near your building blocks.","setup":"Be the one who invites. Say:","yourLine":[{"text":"\"Want to build the tower with me?\"","best":true},{"text":"\"This is just for us, sorry.\""}],"relearn":"A simple \"come play\" makes a friend and shares the fun.","persona":"Aria","source":"inclusion / voice"},
  {"id":"ss-1373","cat":"toys-for-all","type":"role-play","hook":"A friend laughs that you're holding a doll.","setup":"Stand tall and say your line:","yourLine":[{"text":"\"I like dolls, and that's just fine!\"","best":true},{"text":"\"Sorry, I'll put it back.\""}],"relearn":"Your favourite toy is yours to enjoy, proudly.","persona":"Faizan-type","source":"voice / audio-first"},
  {"id":"ss-1374","cat":"toys-for-all","type":"role-play","hook":"Lensy hands you a toy drum and a shy friend.","setup":"Share the beat. Say it aloud:","yourLine":[{"text":"\"Let's drum together, one each!\"","best":true},{"text":"\"This drum is only mine.\""}],"relearn":"Sharing the toy turns one player into two happy friends.","persona":"Kabir","source":"voice / audio-first"},
  {"id":"ss-1375","cat":"toys-for-all","type":"role-play","hook":"A kid says the toy doctor kit is only for boys.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"Anyone can be the doctor, watch me!\"","best":true},{"text":"\"Maybe you're right, I'll stop.\""}],"relearn":"Any kid can play any role; no toy is fenced off by gender.","persona":"Aria","source":"voice / audio-first"},
  {"id":"ss-1376","cat":"toys-for-all","type":"match","hook":"Match each kid to the toy they're reaching for.","pairs":[{"left":"Aanya likes to fix things","right":"A toy toolkit"},{"left":"Rohan likes to feed his teddy","right":"A play feeding-bottle"},{"left":"Meera likes fast races","right":"A toy car"},{"left":"Ishaan likes baking","right":"A play oven"},{"left":"Tara likes towers","right":"A box of blocks"}],"relearn":"Any kid can love any toy; the toy never picks the kid.","persona":"any","source":"gender & play"},
  {"id":"ss-1377","cat":"toys-for-all","type":"match","hook":"Match the toy to the happy thing you can do with it.","pairs":[{"left":"Toy train","right":"Chugging round the track"},{"left":"Tea set","right":"Pouring pretend chai"},{"left":"Skipping rope","right":"Jumping and counting"},{"left":"Soft teddy","right":"A cosy cuddle"},{"left":"Spinning top","right":"Watching it twirl"}],"relearn":"Every toy is a kind of fun, and the fun is open to every kid.","persona":"any","source":"play"},
  {"id":"ss-1378","cat":"toys-for-all","type":"match","hook":"Each toy is sad alone. Match it to a friend to share.","pairs":[{"left":"A lonely doll","right":"A boy keen to care"},{"left":"A waiting cricket bat","right":"A girl keen to bat"},{"left":"A quiet drum","right":"A kid keen on the beat"},{"left":"A still toy car","right":"A kid keen to zoom"},{"left":"An empty play-kitchen","right":"A friend keen to cook"}],"relearn":"Any kid can be the friend a toy is waiting for.","persona":"any","source":"inclusion"},
  {"id":"ss-1379","cat":"toys-for-all","type":"match","hook":"Match each shared toy to a kind, fair thing to say.","pairs":[{"left":"Handing over the ball","right":"\"Your turn now!\""},{"left":"Welcoming a new kid","right":"\"Come play with us!\""},{"left":"Sharing the last block","right":"\"Let's build it together.\""},{"left":"Asking before grabbing","right":"\"May I have a turn?\""},{"left":"Cheering a friend's tower","right":"\"Wow, you built it!\""}],"relearn":"Kind words make sharing toys fun for everyone.","persona":"any","source":"peer norms"},
  {"id":"ss-1380","cat":"toys-for-all","type":"match","hook":"Match each kid's idea to a toy that fits it.","pairs":[{"left":"\"I want to build a zoo\"","right":"Animal figures and blocks"},{"left":"\"I want to cook a feast\"","right":"Pots and a play stove"},{"left":"\"I want to race\"","right":"Two toy cars"},{"left":"\"I want to put baby to sleep\"","right":"A doll and a tiny cot"},{"left":"\"I want to make music\"","right":"A drum and bells"}],"relearn":"Any kid can dream up any play; the toys are there for everyone.","persona":"any","source":"play"},
  {"id":"ss-1381","cat":"toys-for-all","type":"match","hook":"Match the kid to the toy a friend just lent them.","pairs":[{"left":"A boy trying a doll","right":"\"Here, you can pretend too!\""},{"left":"A girl trying the toy bus","right":"\"Drive it round the mat!\""},{"left":"A shy kid trying blocks","right":"\"Stack one on mine!\""},{"left":"A new kid trying the bat","right":"\"Have a swing, it's fun!\""},{"left":"A small kid trying the drum","right":"\"Tap it soft, like this.\""}],"relearn":"Lending a toy says \"this is for you too.\"","persona":"any","source":"inclusion"},
  {"id":"ss-1382","cat":"toys-for-all","type":"build","hook":"Build a shared toy basket for the anganwadi.","prompt":"Drag in toys so every kid finds something.","pieces":["dolls","trucks","skipping rope","play-kitchen","drum","picture puzzle"],"mode":"assemble","key":["dolls","trucks","skipping rope","play-kitchen","drum","picture puzzle"],"relearn":"A great toy basket has something for everyone, and everyone may share it all.","persona":"any","source":"inclusion"},
  {"id":"ss-1383","cat":"toys-for-all","type":"build","hook":"Build the steps for a fair turn with one toy car.","prompt":"Put the sharing steps in order.","pieces":["Ask \"may I have a turn?\"","Wait nicely for your turn","Play with the car","Hand it on with a smile"],"mode":"sequence","key":["Ask \"may I have a turn?\"","Wait nicely for your turn","Play with the car","Hand it on with a smile"],"relearn":"Ask, wait, play, pass it on: that's a fair turn for everyone.","persona":"Aria","source":"fairness"},
  {"id":"ss-1384","cat":"toys-for-all","type":"build","hook":"Build a friendly toy sign for the play corner.","prompt":"Pick the words that welcome every kid.","pieces":["\"Everyone may play\"","\"Take turns\"","\"Girls only\"","\"Share and be kind\""],"mode":"assemble","key":["\"Everyone may play\"","\"Take turns\"","\"Share and be kind\""],"relearn":"A welcoming sign says: everyone plays, take turns, be kind.","persona":"any","source":"inclusion"},
  {"id":"ss-1385","cat":"toys-for-all","type":"build","hook":"Build a play plan to invite a left-out friend.","prompt":"Put the kind steps in order.","pieces":["Spot the kid playing alone","Walk over and smile","Say \"come play with us!\"","Share a toy to start"],"mode":"sequence","key":["Spot the kid playing alone","Walk over and smile","Say \"come play with us!\"","Share a toy to start"],"relearn":"Noticing, inviting, and sharing turns a lonely kid into a playmate.","persona":"Aria","source":"inclusion"},
  {"id":"ss-1386","cat":"toys-for-all","type":"build","hook":"Build a toy shelf where boys and girls share it all.","prompt":"Add toys that any kid can pick.","pieces":["baby doll","toy car","play stove","cricket bat","building blocks","toy drum"],"mode":"assemble","key":["baby doll","toy car","play stove","cricket bat","building blocks","toy drum"],"relearn":"Every toy on the shelf is for every kid; nothing is off-limits.","persona":"Vihaan","source":"gender & play"},
  {"id":"ss-1387","cat":"toys-for-all","type":"build","hook":"Build the steps to start a game everyone can join.","prompt":"Order the steps for fair, fun play.","pieces":["Pick a toy to share","Ask who wants to join","Make turns so all get a go","Play and cheer each other"],"mode":"sequence","key":["Pick a toy to share","Ask who wants to join","Make turns so all get a go","Play and cheer each other"],"relearn":"The best play is planned so every kid gets to join in.","persona":"any","source":"inclusion"},
  {"id":"ss-1388","cat":"toys-for-all","type":"build","hook":"Build a cosy pretend home for play-time.","prompt":"Pick the toys that make a pretend home.","pieces":["play stove","baby doll","tiny plates","toy broom","blocks for walls","soft teddy"],"mode":"assemble","key":["play stove","baby doll","tiny plates","toy broom","blocks for walls","soft teddy"],"relearn":"Any kid can play house; pretend homes are for everyone.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1389","cat":"toys-for-all","type":"build","hook":"Build a fair toy kit for two friends to share.","prompt":"Pick toys both friends can take turns with.","pieces":["one ball","two skipping ropes","a drum to swap","a shared puzzle","a toy car","a tea set"],"mode":"assemble","key":["one ball","two skipping ropes","a drum to swap","a shared puzzle","a toy car","a tea set"],"relearn":"Toys are to share; a fair kit lets both friends play.","persona":"any","source":"fairness"},
  {"id":"ss-1390","cat":"toys-for-all","type":"branch","hook":"A friend grabs the doll and says \"this is mine, not yours.\"","options":[{"text":"Say \"let's take turns, then we both play\"","consequence":"You make a fair plan and both have fun.","outcome":"fair","best":true},{"text":"Grab it back and pull hard","consequence":"The doll might tear and you both feel cross."}],"debrief":"A calm \"let's take turns\" shares the toy and keeps the friend.","relearn":"Taking turns is fair; grabbing isn't.","persona":"Vihaan","source":"fairness"},
  {"id":"ss-1391","cat":"toys-for-all","type":"branch","hook":"A boy wants the play-kitchen and others giggle at him.","options":[{"text":"Say \"anyone can cook, come on!\" and play with him","consequence":"He grins, and the giggling stops.","outcome":"kind","best":true},{"text":"Giggle along so you fit in","consequence":"He feels left out, and that isn't kind."}],"debrief":"Standing with a friend ends the teasing fast.","relearn":"Boys can love the play-kitchen; cheering them on is kind.","persona":"Faizan-type","source":"care & play"},
  {"id":"ss-1392","cat":"toys-for-all","type":"branch","hook":"New kid asks shyly, \"can I play trains with you?\"","options":[{"text":"Smile and say \"yes, here's a carriage!\"","consequence":"You gain a friend and a longer track.","outcome":"kind","best":true},{"text":"Say \"no, only us two play\"","consequence":"The new kid wanders off alone, feeling sad."}],"debrief":"A quick \"yes, join in\" makes a friend.","relearn":"Inviting everyone to play is how good friends play.","persona":"any","source":"inclusion"},
  {"id":"ss-1393","cat":"toys-for-all","type":"branch","hook":"There's one bat and three kids who all want to bat.","options":[{"text":"Set a turn order so each kid bats","consequence":"Everyone gets a go and the game is fun.","outcome":"fair","best":true},{"text":"Keep the bat the whole time yourself","consequence":"The others get bored and stop playing."}],"debrief":"A turn order means no one is left out of the fun.","relearn":"Everyone gets a turn; that's what makes play fair.","persona":"Aria","source":"fairness"},
  {"id":"ss-1394","cat":"toys-for-all","type":"branch","hook":"A kid tells a girl \"blocks aren't for you, give them here.\"","options":[{"text":"Say \"blocks are for everyone\" and build beside her","consequence":"She stays, and you build a big tower together.","outcome":"fair","best":true},{"text":"Stay quiet and let her be shooed away","consequence":"She leaves sadly, and the silly rule wins."}],"debrief":"Speaking up kindly keeps a friend in the game.","relearn":"No one can tell a kid a toy isn't for her.","persona":"any","source":"peer norms"},
  {"id":"ss-1395","cat":"toys-for-all","type":"branch","hook":"Your little cousin wants to join your doll game.","options":[{"text":"Give them a doll and show them how","consequence":"They beam, and your game grows bigger.","outcome":"kind","best":true},{"text":"Say \"you're too little, go away\"","consequence":"They feel left out and start to cry."}],"debrief":"Sharing the play makes the game warmer for all.","relearn":"Toys are to share; inviting others in is kind.","persona":"any","source":"inclusion"},
  {"id":"ss-1396","cat":"toys-for-all","type":"branch","hook":"A friend says \"don't play with that pink truck, it's babyish.\"","options":[{"text":"Say \"I like it!\" and keep zooming it","consequence":"You have fun, and your friend joins in too.","outcome":"fair","best":true},{"text":"Drop it so they won't tease you","consequence":"You miss out on the toy you actually love."}],"debrief":"Your favourite toy is yours to enjoy, proudly.","relearn":"No toy is \"wrong\" for you; play with what you love.","persona":"Vihaan","source":"autonomy"},
  {"id":"ss-1397","cat":"toys-for-all","type":"reflect","hook":"Lensy wonders: which toy makes YOU happiest?","prompt":"Point to one.","options":["A doll","A truck","Building blocks","A drum"],"affirm":"Whatever you love is just right for you. Every toy is for everyone.","relearn":"Your favourite play is yours; no toy is off-limits.","persona":"any","source":"autonomy"},
  {"id":"ss-1398","cat":"toys-for-all","type":"reflect","hook":"What would you love to pretend to be today?","prompt":"Tap one to play.","options":["A cook","A driver","A doctor","A builder"],"affirm":"Any kid can pretend to be anything. Pick what feels fun!","relearn":"Any toy and any role is open to every kid.","persona":"Aria","source":"autonomy"},
  {"id":"ss-1399","cat":"toys-for-all","type":"reflect","hook":"A new friend is here. What toy will you share first?","prompt":"Choose one to offer.","options":["My blocks","My toy car","My doll","My drum"],"affirm":"Sharing any toy is a lovely way to say \"come play.\"","relearn":"Toys are to share; sharing makes friends.","persona":"any","source":"inclusion"},
  {"id":"ss-1400","cat":"toys-for-all","type":"reflect","hook":"How do you like to play best?","prompt":"Point to your favourite way.","options":["Building things","Caring for toys","Running games","Making music"],"affirm":"Every way to play is wonderful, and it's all for you.","relearn":"Your favourite play is yours, whoever you are.","persona":"any","source":"autonomy"},
  {"id":"ss-1401","cat":"toys-for-all","type":"reflect","hook":"Megha-moment: which toy will you teach a grown-up to play?","prompt":"Pick one to show them.","options":["The play-kitchen","The blocks","The doll","The toy car"],"affirm":"Showing a grown-up your play is the best; they'll see toys are for all.","relearn":"Play is to share; invite your grown-ups in.","persona":"Megha","source":"co-play"},
  {"id":"ss-1402","cat":"toys-for-all","type":"reflect","hook":"If your toy box could hold one more thing, what would you add?","prompt":"Tap your pick.","options":["A soft teddy","A skipping rope","A toy train","A tea set"],"affirm":"Whatever you'd add is a happy choice; every toy is for everyone.","relearn":"There are no wrong toys; there's just what you enjoy.","persona":"any","source":"autonomy"},
  {"id":"ss-1403","cat":"toys-for-all","type":"reflect","hook":"Which friend will you invite to play your favourite game?","prompt":"Think of one and tap.","options":["A new kid","A quiet kid","My cousin","My best friend"],"affirm":"Inviting anyone in is how kind friends play. Lovely choice!","relearn":"Inviting everyone to play is how good friends play.","persona":"Aria","source":"inclusion"},
  {"id":"ss-1404","cat":"toys-for-all","type":"reflect","hook":"What sound does your favourite toy make in your head?","prompt":"Pick the one you hear.","options":["Vroom!","Ting-ting!","Dhum-dhum!","Shh, sleep now"],"affirm":"Any toy and any sound is yours to enjoy. Play on!","relearn":"Your favourite play is yours; no toy is off-limits.","persona":"Kabir","source":"autonomy"},
];

